BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عمار بن ياسر بن عامر ابن مالك بن كنانة بن قيس بن الحصين بن الوذيم بن ثعلبة بن عوف بن حارثة بن عامر الأكبر بن يام بن عنس بن مالك بن أدد بن زيد بن يشجب المذحجي ثم العنسي أبو اليقظان وهو من السابقين الأولين إلى الإسلام وهو حليف بني مخزوم وأمه سمية وهي أول من استشهد في سبيل الله عز وجل وهو وأبوه وأمه من السابقين وكان إسلام عمار بعد بضعة وثلاثين وهو ممن عذب في الله وقال الواقدي وغيره من أهل العلم بالنسب والخبران ياسرا والد عمار عرني قحطاني مذحجي من عنس إلا أن ابنه عمارا مولى لبني مخزوم لأن أباه ياسرا تزوج أمة لبعض بني مخزوم فولدت له عمارا وكان سبب قدوم ياسر مكة أنه قدم هو وأخوان له يقال لهما الحارث ومالك في طلب أخ لهما رابع فرجع الحارث ومالك إلى اليمن وأقام ياسر بمكة فحالف أبا حذيفة ابن المغيرة بن عبد الله بن عمر بن مخزوم وتزوج أمة له يقال لها سمية فولدت له
عمارا فأعتقه أبو حذيفة فمن ههنا صار عمار مولى لبني مخزوم وأبوه عرني كما ذكرنا وأسلم عمار ورسول الله صلى الله عليه وسلم في دار الأرقم هو وصهيب بن سنان في وقت واحد قال عمار لقيت صهيب بن سنان على باب دار الأرقم ورسول الله صلى الله عليه وسلم فيها فقلت ما تريد فقال وما تريد أنت فقلت أردت أن أدخل على محمد وأسمع كلامه فقال وأنا أريد ذلك فدخلنا عليه فعرض علينا الإسلام فأسلمنا وكان إسلامهما بعد بضعة وثلاثين رجلا وروى يحيى بن معين عن إسماعيل بن مجالد عن مجالد عن بيان عن وبرة عن همام قال سمعت عمارا يقول رأيت رسول الله صلى الله عليه وسلم وما معه إلا خمسة أعبد وامرأتان وأبو بكر وقال مجاهد أول من أظهر إسلامه سبعة رسول الله وأبو بكر وبلال وخباب وصهيب وعمار وأمه سمية واختلف في هجرته إلى الحبشة وعذب في الله عذابا شديدا أنبأنا أبو محمد عبد الله بن علي بن سويدة التكريتي بإسناده إلى أبي الحسن علي بن أحمد بن متويه في قوله عز وجل من كفر بالله من بعد إيمانه الامن أكره وقلبه مطمئن بالإيمان نزلت في عمار بن ياسر أخذه المشركون فعذبوه فلم يتركوه حتى سب النبي صلى الله عليه وسلم وذكر آلهتهم بخير ثم تركوه فلما أتى رسول الله صلى الله عليه وسلم قال ما وراءك قال شر يا رسول الله ما تركت حتى نلت منك وذكرت آلهتهم بخير قال كيف تجد قلبك قال مطمئنا بالإيمان قال فإن عادوا لك فعد لهم أخبرنا أبو جعفر عبيد الله ابن أحمد بإسناده إلى يونس بن بكير عن ابن إسحاق قال حدثني رجال من آل عمار ابن ياسر أن سمية أم عمار عذبها هذا الحي من بني المغيرة بن عبد الله بن عمر بن مخزوم على الإسلام وهي تأبى غيره حتى قتلوها وكان رسول الله صلى الله عليه وسلم مر بعمار وأمه وأبيه وهم يعذبون بالأبطح في رمضاء مكة فيقول صبرا آل ياسر موعدكم الجنة قال وحدثنا يونس عن عبد الله بن عون عن محمد بن سيرين قال مر رسول الله صلى الله عليه وسلم بعمار بن ياسر وهو يبكي يدلك عينيه فقال رسول الله صلى الله عليه وسلم مالك أخذك الكفار فغطوك في الماء فقلت كذا وكذا فإن عادوا لك فقل كما قلت قال وحدثنا يونس عن ابن إسحاق قال حدثني حكيم بن جبير عن سعيد بن جبير قال قلت لابن عباس أكان المشركون يبلغون من المسلمين في العذاب ما يعذرون به في ترك دينهم فقال نعم والله إن كانوا ليضربون أحدهم ويجيعونه ويعطشونه حتى ما يقدر على أن يستوي جالسا من شدة الضر الذي به حتى إنه ليعطيهم ما سألوه من الفتنة وحتى يقولوا له اللات والعزى إلهك من دون الله فيقول نعم وحتى إن الجعل ليمر بهم فيقولون له هذا الجعل إلهك من دون الله فيقول نعم افتداء لما يبلغون من جهده وهاجر إلى المدينة وشهد بدرا وأحدا والخندق وبيعة الرضوان مع رسول الله صلى الله عليه وسلم أنبأنا عبيد الله بن أحمد ابن علي بإسناده عن يونس بن بكير عن ابن إسحاق في تسمية من شهد بدرا من بني مخزوم قال وعمار بن ياسر وكلهم قالوا إنه شهد بدرا وأحدا وغير هما أنبأنا أبو البركات الحسن بن محمد بن الحسن الدمشقي بها أنبأنا أبو العشائر محمد بن خليل بن فارس أنبأنا الفقيه أبو القاسم علي بن محمد بن علي المصيصي أنبأنا أبو محمد عبد الرحمن بن عثمان ابن القاسم بن أبي نصر أنبأنا أبو الحسن خيثمة بن سليمان بن حيدرة الأطرابلسي حدثنا إبراهيم بن أبي سفيان القيسراني حدثنا محمد بن يوسف الغرياني حدثنا الثوري عن عبد الملك بن عمير عن مولى لربعي بن خراش عن حذيفة بن اليمان قال قال رسول الله صلى الله عليه وسلم اقتدوا باللذين من بعدي أبي بكر وعمر واهتدوا بهدي عمار وتمسكوا بعهد ابن أم عبد أنبأنا أبو ياسر بن أبي حبة بإسناده عن عبد الله بن أحمد بن حنبل حدثني أبي حدثنا يزيد بن هارون حدثنا العوام يعني ابن حوشب عن سلمة بن كهبل عن علقمة عن خالد بن الوليد قال كان بيني وبين عمار كلام فأغلظت له في القول فانطلق عمار يشكوني إلى النبي صلى الله عليه وسلم فجاء خالد وهو يشكوه إلى النبي صلى الله عليه وسلم قال فجعل يغلظ له ولا يزيده إلا غلظة والنبي صلى الله عليه وسلم ساكت لا يتكلم فبكى عمار وقال يا رسول الله ألا تراه فرفع رسول الله صلى الله عليه وسلم رأسه وقال من عادى عمارا عاداه الله ومن أبغض عمارا أبغضه الله قال خالد فخرجت فما كان شئ أحب إلي من رضى عما فلقيته فرضي وأنبأنا عبد الله بن أحمد حدثني أبي حدثنا وكيع حدثنا سفيان عن أبي إسحاق عن هانئ بن هاني عن علي قال جاء عمار يستأذن على النبي صلى الله عليه وسلم فقال ائذنوا له مرحبا بالطيب المطيب أنبأنا إبراهيم بن محمد وغير واحد بإسنادهم عن أبي عيسى الترمذي قال حدثنا القاسم بن دينار الكوفي حدثنا عبيد الله ابن موسى عن عبد العزيز بن سياه عن حبيب بن أبي ثابت عن عطاء بن يسار عن عائشة قالت قال رسول الله صلى الله عليه وسلم ما خير عمار بين أمرين إلا اختار أرشدهما قال وحدثنا الترمذي حدثنا أبو مصعب المديني حدثنا عبد العزيز بن 
محمد عن العلاء بن عبد الرحمن عن أبيه عن أبي هريرة قال قال رسول الله صلى الله عليه وسلم أبشر عمار تقتلك الفئة الباغية وقد روى نحو هذا عن أم سلمة وعبد الله ابن عمرو بن العاص وحذيفة وروى شعبة أن رجلا قال لعمار أيها العبد الاجدع قال عمار سب خير أذني قال شعبة وكانت أصيبت مع رسول الله صلى الله عليه وسلم وهذا وهم من شعبة والصواب أنها أصيبت يوم اليمامة
(ومن مناقبه) أنه أول من بنى مسجدا في الإسلام أنبأنا عبيد الله بن أحمد بن علي بإسناده إلى يونس بن بكير عن عبد الرحمن بن عبد الله عن الحكم بن عيينة قال قدم رسول الله صلى الله عليه وسلم المدينة أول ما قدمها ضحى فقال عمار ما لرسول الله صلى الله عليه وسلم بد من أن نجعل له مكانا إذا استظل من قائلته ليستظل فيه ويصلي فيه فجمع حجارة فبنى مسجد قباء فهو أول مسجد بني وعمار بناه أنبأنا إسماعيل بن علي وغيره بإسنادهم عن محمد ابن عيسى أنبأنا عمرو بن علي حدثنا يزيد بن زريع حدثنا سعيد عن قتادة عن عروة عن سعيد بن عبد الرحمن بن أبزى عن أبيه عن عمار بن ياسر أن النبي صلى الله عليه وسلم أمره بالتيمم للوجه والكفين وشهد عمار قتال مسيلمة فروى نافع عن ابن عمر قال رأيت عمار بن ياسر يوم اليمامة على صخرة قد أشرف يصيح يا معشر المسلمين أمن الجنة تفرون إلي إلي أنا عمار بن ياسر هلموا إلي قال وأنا أنظر إلى أذنه قد قطعت فهي تذبذب وهو يقاتل أشد القتال ومناقب عمار المروية كثيرة اقتصرنا منها على هذا القدر واستعمله عمر بن الخطاب على الكوفة وكتب إلى أهلها أما بعد فإني قد بعثت إليكم عمارا أميرا وعبد الله بن مسعود وزيرا ومعلما وهما من نجباء أصحاب محمد فاقتدوا بهما ولما عزله عمر قال له أساءك العزل قال والله لقد ساءتني الولاية وساءني العزل ثم إنه بعد ذلك صحب عليا رضي الله عنهما وشهد معه الجمل وصفين فأبلى فيهما قال أبو عبد الرحمن السلمي شهدنا صفين مع علي فرأيت عمار بن ياسر لا يأخذ في ناحية ولا واد من أودية صفين إلا رأيت أصحاب النبي صلى الله عليه وسلم يتبعونه كأنه علم لهم قال وسمعته يومئذ يقول لهاشم بن عتبة بن أبي وقاص يا هاشم تفر من الجنة الجنة تحت البارقة اليوم ألقى الا حبه محمدا وحزبه والله لو ضربونا حتى يبلغوا بنا شعاب هجر لعلمت أنا على حق وأنهم على الباطل وقال أبو البحتري قال عمار بن ياسر يوم صفين ائتوني بشربة فأتي بشربة لبن فقال إن رسول الله صلى الله عليه وسلم قال آخر شربة تشربها من الدنيا شربة لبن وشربها ثم قاتل حتى قتل وكان

عمره يومئذ أربعا وتسعين سنة وقيل ثلاث وتسعون وقيل إحدى وتسعون وروى عمارة بن خزيمة بن ثابت قال شهد خزيمة بن ثابت الجمل وهو لا يسل سيفا وشهد صفين ولم يقاتل وقال لا أقاتل حتى يقتل عمار فأنظر من يقتله فإني سمعت رسول الله صلى الله عليه وسلم يقول تقتله الفئة الباغية فلما قتل عمار قال خزيمة ظهرت لي الضلالة ثم تقدم فقاتل حتى قتل ولما قتل عمار قال ادفنوني في ثيابي فإني مخاصم وقد اختلف في قاتله فقيل قتله أبو العادية المزني وقيل الجهني طعنة فسقط فلما وقع أكب عليه آخر فاحتز رأسه فأقبلا يختصمان كل منهما يقول أنا قتلته فقال عمرو بن العاص والله إن يختصمان إلا في النار والله لوددت أني مت قبل هذا اليوم بعشرين سنة وقيل حمل عليه عقبة بن عامر الجهني وعمرو بن حارث الخولاني وشريك بن سلمة المرادي فقتلوه وكان قتله في ربيع الأول أو الآخر من سنة سبع وثلاثين ودفنه علي في ثيابه ولم يغسله وروى أهل الكوفة أنه صلى عليه وهو مذهبهم في الشهيد أنه يصلى عليه ولا يغسل وكان عمار آدم طويلا مضطربا أشهل العينين بعيد ما بين المنكبين وكان لا يغير شيبه وقيل كان أصلع في مقدم رأسه شعرات وله أحاديث روى عنه علي بن أبي طالب وابن عباس وأبو موسى وجابر وأبو أمامة وأبو الطفيل وغيرهم من الصحابة وروى عنه من التابعين ابنه محمد بن عمار وابن المسيب وأبو بكر بن عبد الرحمن ومحمد بن الحنفية وأبو وائل وعلقمة وزرين حبيش وغيرهم أخرجه الثلاثة'
WHERE id = 67
  AND content_ar LIKE '(ب د ع) عمار بن ياسر%'
  AND source_codes IS NULL;

