    content_ar = 'مصعب بن عمير بن هاشم بن عبد مناف ابن عبد الدار بن قصي بن كلاب بن مرة القرشي العبدري يكنى أبا عبد الله كان من فضلاء الصحابة وخيارهم ومن السابقين إلى الإسلام أسلم ورسول الله صلى الله
عليه وسلم في دار الأرقم وكتم إسلامه خوفا من أمه وقومه وكان يختلف إلى رسول الله صلى الله عليه وسلم سرا فبصر به عثمان بن طلحة العبدري يصلي فأعلم أهله وأمه فأخذوه فحبسوه فلم يزل محبوسا إلى أن هاجر إلى أرض الحبشة وعاد من الحبشة إلى مكة ثم هاجر إلى المدينة بعد العقبة الأولى ليعلم الناس القرآن ويصلي بهم أخبرنا عبيد الله بن أحمد بإسناده إلى يونس بن بكير عن ابن إسحاق عن يزيد بن أبي حبيب قال لما انصرف القوم عن رسول الله صلى الله عليه وسلم يعني ليلة العقبة الأولى بعث معهم مصعب بن عمير قال ابن إسحاق وحدثنح عاصم بن عمر بن قتادة أن مصعب بن عمير كان يصلي بهم وذلك أن الأوس والخزرج كره بعضهم أن يؤمه بعض قال ابن إسحاق وحدثني عبيد الله بن أبي بكر بن حزم وعبيد الله بن المغيرة بن معيقيب قالا بعث رسول الله صلى الله عليه وسلم مصعب بن عمير مع النفر الاثني عشر الذين بايعوه في العقبة الأولى يفقه أهلها ويقرئهم القرآن فكان منزله على أسعد ابن زرارة وكان إنما يسمى بالمدينة المقرئ يقال إنه أول من جمع الجمعة بالمدينة وأسلم على يده أسيد بن حضير وسعد بن معاذ وكفى بذلك فخرا وأثرا في الإسلام قال البراء بن عازب أول من قدم علينا من المهاجرين بن مصعب بن عمير أخو بني عبد الدار ثم أتانا بعده عمرو ابن أم مكتوم ثم أتانا بعده عمار بن ياسر وسعد بن أبي وقاص وعبد الله بن مسعود وبلال ثم أتانا عمر بن الخطاب وشهد مصعب بدرا مع رسول الله صلى الله عليه وسلم وشهد أحدا ومعه لواء رسول الله صلى الله عليه وسلم وقتل بأحد شهيدا قتله ابن قمئة الليثي في قول ابن إسحاق أخبرنا أبو جعفر بإسناده عن يونس عن ابن إسحاق فيمن استشهد من المسلمين من بني عبد الدار مصعب بن عمير بن هاشم قتله ابن قمئة الليثي قيل كان عمره يوم قتل أربعين سنة أو أكثر قليلا ويقال فيه نزلت وفي أصحابه من المؤمنين رجال صدقوا ما عاهدوا الله عليه الآية وروى محمد بن إسحاق عن صالح بن كيسان عن بعض آل سعد عن سعد ابن أبي وقاص قال كنا قوما يصيبنا ظلف العيش بمكة مع رسول الله صلى الله عليه وسلم فلما أصابنا البلاء اعترفنا ومررنا عليه فصبرنا وكان مصعب بن عمير أنعم غلام بمكة وأجوده حلة مع أبويه ثم لقد رأيته جهد في الإسلام جهدا شديدا حتى لقد رأيت جلده يتحشف كما يتحشف جلد الحية وقال الواقدي كان مصعب بن عمير فتى مكة شبابا وجمالا وسيبا وكان أبواه يحبانه وكانت أمه تكسوه أحسن ما يكون * تنبية * ظلف العيش وشدته وكذا في النهاية * من الثياب وكان أعطر أهل مكة وكان رسول الله صلى الله عليه وسلم يذكره ويقول ما رأيت بمكة أحسن لمة ولا أنعم نعمة من مصعب بن عمير أخبرنا إسماعيل بن علي وغيره بإسنادهم عن محمد بن عيسى حدثنا هناد حدثنا يونس بن بكير عن محمد بن إسحاق حدثني يزيد بن زياد عن محمد بن كعب القرظي قال حدثني من سمع علي بن أبي طالب رضي الله عنه يقول إنا لجلوس مع رسول الله صلى الله عليه وسلم في المسجد إذ طلع علينا مصعب بن عمير وما عليه إلا بردة له مرقوعة بفرو فلما رآه رسول الله صلى الله عليه وسلم بكى للذي كان فيه من النعمة والذي هو فيه اليوم ثم قال رسول الله صلى الله عليه وسلم كيف بكم إذا غدا أحدكم في حلة وراح في حلة ووضعت بين يديه صحفة ورفعت أخرى وسترتم بيوتكم كما تستر الكعبة قالوا يا رسول الله نحن يومئذ خير منا اليوم نتفرغ للعبادة ونكفى المؤنة فقال رسول الله صلى الله عليه وسلم أنتم اليوم خير منكم يومئذ قال وأخبرنا محمد بن عيسى حدثنا محمود بن غيلان حدثنا أبو أحمد حدثنا أبو سفيان عن الأعمش عن أبي وائل عن خباب قال هاجرنا مع رسول الله صلى الله عليه وسلم نبتغي وجه الله عز وجل فوقع أجرنا على الله فمنا من مات لم يأكل من أجره شيئا ومنا من أينعت له ثمرته فهو يهديها وإن مصعب بن عمير مات ولم يترك إلا ثوبا كان إذا غطوا رأسه خرجت رجلاه وإذا غطوا به رجليه خرج رأسه فقال رسول الله صلى الله عليه وسلم غطوا رأسه واجعلوا على رجليه الإذخر أخبرنا أبو محمد بن أبي القاسم بن الحافظ كتابة حدثنا أبي حدثنا أحمد بن الحسن حدثنا أبو الحسين بن أبي موسى حدثنا إبراهيم بن محمد حدثنا محمد بن سفيان حدثنا سعيد بن رحمة قال سمعت ابن المبارك عن وهب بن مطر عن عبيد بن عمير قال وقف رسول الله صلى الله عليه وسلم على مصعب بن عمير وهو منجعف على وجهه يوم أحد شهيدا وكان صاحب لواء رسول الله صلى الله عليه وسلم فقال رسول الله صلى الله عليه وسلم من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا إن رسول الله يشهد عليكم أنكم شهداء عند الله يوم القيامة ثم أقبل على الناس فقال أيها الناس ائتوهم فزوروهم وسلموا عليهم فوالذي نفسي بيده لا يسلم عليهم أحد إلى يوم القيامة إلا ردوا عليه¬ السلام ولم يعقب مصعب إلا من ابنته زينب أخرجه الثلاثة'
WHERE id = 68
  AND content_ar LIKE '(ب د ع) مصعب بن عمير%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 68;

-- id=69  عبيدة بن الحارث بن المطلب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 69;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبيدة بضم العين وفتح الباء هو عبيدة بن الحارث بن المطلب بن عبد مناف بن قصي القرشي المطلبي يكنى أبا الحارث وقيل أبو معاوية وأمه وأم أخويه سخيلة بنت خزاعي بن الحويرث الثقفية وكان أسن من رسول الله صلى الله عليه وسلم بعشر سنين وكان إسلامه قبل

دخول رسول الله صلى الله عليه وسلم دار الأرقم بن أبي الأرقم أسلم هو وأبو سلمة بن عبد الأسد وعبد الله بن الأرقم المخزومي وعثمان بن مظعون في وقت واحد وهاجر عبيدة إلى المدينة مع أخويه طفيل والحصين ابني الحارث ومع مسطح بن أثاثة بن عبادة بن المطلب ونزلوا على عبد الله بن سلمة العجلاني وكان لعبيدة قدر ومنزلة كبيرة عند رسول الله صلى الله عليه وسلم أخبرنا أبو جعفر بن السمين بإسناده إلى يونس بن بكير عن ابن إسحاق قال فأقام رسول الله صلى الله عليه وسلم بالمدينة يعني بعد عوده من غزوة ودان بقية صفر وصدرا من ربيع الأول السنة الأولى من الهجرة وبعث في مقامه ذلك عبيدة بن الحارث بن المطلب في ستين راكبا من المهاجرين ليس فيهم من الأنصار أحد فكان أول لواء عقده رسول الله صلى الله عليه وسلم فالتقى عبيدة والمشركون بثنية المرة وكان على المشركين أبو سفيان بن حرب وكان أول من رمي بسهم في سبيل الله سعد بن مالك وكان هذا أول قتال كان في الإسلام ثم شهد عبيدة بدرا قال وحدثنا يونس عن ابن إسحاق قال ثم خرج عتبة وشيبة ابنا ربيعة والوليد بن عتبة فدعوا إلى البراز فخرج إليهم فتية من الأنصار ثلاثة فقالوا ممن أنتم قالوا رهط من الأنصار قالوا مالنا إليكم حاجة ثم نادى مناديهم يا محمد اخرج إلينا أكفاءنا من قومنا فقال رسول الله صلى الله عليه وسلم قم يا حمزة قم يا علي قم يا عبيدة فبارز عبيدة عتبة فاختلفا ضربتين كلاهما أثبت صاحبه وبارز حمزة شيبة فقتله مكانه وبارز علي الوليد فقتله مكانه ثم كرا على عتبة فذففا عليه واحتملا عبيدة فحازوه إلى الرحل قيل إن عبيدة كان أسن المسلمين يوم بدر فقطعت رجله فوضع رسول الله صلى الله عليه وسلم رأسه على ركبته فقال يا رسول الله لو رآني أبو طالب لعلم أني أحق بقوله منه حيث يقول

ونسلمه حتى نصرع حولهونذهل عن أبنائنا والحلائل
وعاد مع رسول الله صلى الله عليه وسلم من بدر فتوفي بالصفراء قيل أن النبي صلى الله عليه وسلم لما نزل مع أصحابه بالتاربين قال له أصحابه إنا نجد ريح مسك فقال وما يمنعكم وها هنا قبر أبي معاوية وقبل كان عمره حين قتل ثلاثة وستين سنة وكان مربوعا حسن الوجه أخرجه الثلاثة'
WHERE id = 69
  AND content_ar LIKE '(ب د ع) عبيدة بضم ال%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 69;


