-- id=71  خباب بن الأرت
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 71;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'خباب بن الأرت اختلف في نسبه فقيل خزاعي وقيل تميمي وهو الأكثر وهو خباب بن الأرت بن جندلة بن سعد بن خزيمة بن كعب بن سعد بن زيد مناة بن تميم يكنى أبا عبد الله وقيل أبو محمد وقيل أبو يحيى وهو عربي لحقه سباء في الجاهلية فبيع بمكة وقيل هو حليف بني زهرة وقال ابن منده وأبو نعيم قيل هو مولى عتبة بن غزوان وقيل مولى أم أنمار بنت سباع الخزاعية وهي من حلفاء بني زهرة فهو تميمي النسب خزاعي الولاء زهري الحلف لأن مولاته أم أنمار كانت من حلفاء عوف بن عبد عوف بن عبد الحارث بن زهرة والد عبد الرحمن بن عوف وهو من السابقين الأولين إلى الإسلام وممن يعذب في الله تعالى كان سادس ستة في الإسلام قال مجاهد أول من أظهر إسلامه رسول الله صلى الله عليه وسلم وأبو بكر وخباب وصهيب وبلال وعمار وسمية أم عمار فأما رسول الله صلى الله عليه وسلم فمنعه الله بعمه أبي طالب وأما أبو بكر فمنعه قومه وأما الآخرون فألبسوهم أدراع الحديد ثم صهر وهم في الشمس فبلغ منهم الجهد ما شاء الله أن يبلغ من حر الحديد والشمس قال الشعبي إن خبابا صبر ولم يعط الكفار ما سألوا فجعلوا يلصقون ظهره بالرضف حتى ذهب لحم متنه أخبرنا أبو الفضل بن أبي الحسن بن أبي عبد الله الفقيه بإسناده إلى أحمد بن علي الموصلي قال حدثنا زهير بن حرب أخبرنا جرير عن إسماعيل بن قيس عن خباب قال شكونا إلى رسول الله صلى الله عليه وسلم وهو متوسد ببرد له في ظل الكعبة فقلنا ألا تستنصر لنا فجلس محمرا وجهه فقال قد كان من قبلكم يؤخذ الرجل فيحفر له في الأرض ثم يجاء بالميشار فيجعل فوق رأسهما يصرفه عن دينه ويمشط بأمشاط الحديد ما دون لحمه من عظم وعصب ما يصرفه عن دينه وليتمن الله هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخشى إلا الله عز وجل والذئب على غنمه ولكنكم تعجلون وقال أبو صالح كان خباب قينا يطبع السيوف وكان رسول الله صلى الله عليه وسلم يألفه ويأتيه فأخبرت مولاته بذلك فكانت تأخذ الحديدة المحماة فتضعها على رأسه فشكا ذلك إلى رسول الله صلى الله عليه وسلم فقال اللهم انصر خبابا فاشتكت مولاته أم أنمار رأسها فكانت تعوي مثل الكلاب فقيل لها اكتوي فكان خباب يأخذ الحديدة المحماة فيكوي بها رأسها وشهد بدرا وأحدا والمشاهد كلها مع
رسول الله صلى الله عليه وسلم قال الشعبي سأل عمر بن الخطاب خبابا رضي الله عنهما عما لقي من المشركين فقال يا أمير المؤمنين نظر إلى ظهري فنظر فقال ما رأيت كاليوم ظهر رجل قال خباب لقد أوقدت نار وسحبت عليها فما أطفأها إلا ودك ظهري ولما هاجر آخى رسول الله صلى الله عليه وسلم بينه وبين تميم مولى خراش بن الصمة وقيل آخى بينه وبين جبر بن عتيك روى عنه ابنه عبد الله ومسروق وقيس ابن أبي حازم وشقيق وعبد الله بن سخبرة وأبو ميسرة عمرو بن شرحبيل والشعبي وحارثة بن مضرب وغيرهم أخبرنا أبو إسحاق إبراهيم بن محمد الفقيه وغير واحد قالوا بإسنادهم إلى محمد بن عيسى السلمي حدثنا محمد بن بشار أخبرنا وهب بن جرير أخبرنا أبي قال سمعت النعمان بن راشد عن الزهري عن عبد الله بن الحارث عن عبد الله ابن خباب بن الأرت عن أبيه قال صلى رسول الله صلى الله عليه وسلم صلاة فأطالها فقالوا يا رسول الله صليت صلاة لم تكن تصليها قال أجل إنها صلاة رغبة ورهبة إني سألت الله عز وجل فيها ثلاثا فأعطاني اثنتين ومنعني واحدة سألته أن لا يهلك أمتي بسنة فأعطانيها وسألته أن لا يسلط عليهم عدوا من غيرهم فأعطانيها وسألته أن لا يذيق بعضهم بأس بعض فمنعنيها أخبرنا أبو الفرج بن أبي الرجاء أخبرنا أبو الفتح إسماعيل بن الفضل بن أحمد بن الإخشيد أخبرنا أبو طاهر محمد بن عبد الرحيم أخبرنا أبو حفص عمر بن إبراهيم الكناني أخبرنا أبو القاسم البغوي أخبرنا أبو خيثمة زهير بن حرب أخبرنا جرير عن الأعمش عن مالك بن الحارث عن أبي خالد شيخ من أصحاب عبد الله قال بينما نحن في المسجد إذ جاء خباب بن الأرت فجلس فسكت فقال له القوم إن أصحابك قد اجتمعوا إليك لتحدثهم أو لتأمرهم قال بم آمرهم ولعلي آمرهم بما لست فاعلا وروى قيس بن مسلم عن طارق قال عاد خبابا نفر من أصحاب رسول الله صلى الله عليه وسلم فقالوا أبشر أبا عبد الله ترد على إخوانك الحوض فقال إنكم ذكرتم لي إخوانا مضوا ولم ينالوا من أجورهم شيئا وإنا بقينا بعدهم حتى نلنا من الدنيا ما نخاف أن يكون ثوابا لتلك الأعمال ومرض خباب مرضا شديدا طويلا أخبرنا يحيى بن محمود بن سعد بإسناده إلى مسلم بن الحجاج أخبرنا أبو بكر بن أبي شيبة أخبرنا عبد الله بن إدريس عن إسماعيل بن أبي خالد عن قيس ابن أبي حازم قال دخلنا على خباب وقد اكتوى سبع كيات فقال لولا أن رسول الله صلى الله عليه وسلم نهانا أن ندعو بالموت لدعوت به ونزل الكوفة ومات بها وهو أول 
من دفن بظهر الكوفة من الصحابة وكان موته سنة سبع وثلاثين قال زيد بن وهب سرنا مع علي حين رجع من صفين حتى إذا كان عند باب الكوفة إذا نحن بقبور سبعة عن أيماننا فقال ما هذه القبور فقالوا يا أمير المؤمنين إن خباب بن الأرت توفي بعد مخرجك إلى صفين فأوصى أن يدفن في ظاهر الكوفة وكان الناس إنما يدفنون موتاهم في أفنيتهم وعلى أبواب دورهم فلما رأوا خبابا أوصى أن يدفن بالظهر دفن الناس فقال علي رضي الله عنه رحم الله خبابا أسلم راغبا وهاجر طائعا وعاش مجاهدا وابتلى في جسمه ولن يضيع الله أجر من أحسن عملا ثم دنا من قبورهم فقال السلام عليكم يا أهل الديار من المؤمنين والمسلمين أنتم لنا سلف فارط ونحن لكم تبع عما قليل لاحق اللهم أغفر لنا ولهم وتجاوز بعفوك عنا وعنهم طوبى لمن ذكر المعاد وعمل للحساب وقنع بالكفاف وأرضي الله عز وجل قال أبو عمر مات خباب سنة سبع وثلاثين بعد ما شهد صفين مع علي رضي الله عنه والنهروان وصلى عليه علي وكان عمره إذ مات ثلاثا وسبعين سنة قال وقيل مات سنة تسع عشرة وصلى عليه عمر رضي الله عنه أخرجه الثلاثة قلت الصحيح أنه مات سنة سبع وثلاثين وأنه لم يشهد صفين فإنه كان مرضه قد طال به فمنعه من شهودها وأما الخباب الذي مات سنة تسع عشرة هو مولى عتبة بن غزوان ذكره أبو عمر أيضا وقد ذكر ابن منده وأبو نعيم إن خباب بن الأرت مولى عتبة بن غزوان وليس كذلك إنما خباب مولى عتبة بن غزوان آخر يرد ذكره وهما قد ذكرا في تسمية من شهد بدرا خباب بن الأرت من حلفاء بني زهرة ثم ذكرا في ترجمة خباب مولى عتبة من شهد بدرا من بني نوفل بن عبد مناف من حلفائهم عتبة بن غزوان وخباب مولى عتبة ثم قال أبو نعيم عن مولى عتبة إنه لم يعقب ولا تعرف له رواية فكفى بهذا دليلا على أنهما اثنان لأن ابن الأرت قد أعقب عدة أولاد منهم عبد الله وقتلته الخوارج أيام علي رضي الله عنه وله رواية عن النبي صلى الله عليه وسلم ثم إن بني زهرة غير بني نوفل وقد ذكر ابن إسحاق وغيره من أصحاب السير من شهد بدرا من بني زهرة من حلفائهم خباب بن الأرت وذكروا أيضا من حلفاء بني نوفل خبابا مولى عتبة بن غزوان فظهر أن مولى عتبة غير خباب بن الأرت وقال بعض العلماء أن خباب بن الأرت لم يكن قينا وإنما القين خباب مولى عتبة بن غزوان والله أعلم'
WHERE id = 71
  AND content_ar LIKE '(ب د ع) خباب بن الأر%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 71;

