UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبد الله بن رواحة بن ثعلبة بن امرئ القيس بن عمرو بن امرئ القيس الأكبر بن مالك الأغر بن ثعلبة بن كعب بن الخزرج بن الحارث بن الخزرج الأنصاري الخزرجي ثم من بني الحارث يكنى أبا محمد وقيل أبو رواحة وقيل أبو عمرو
وأمه كبشة بنت واقد بن عمرو بن الإطنابة من بني الحارث بن الخزرج أيضا وكان ممن شهد العقبة وكان نقيب بني الحارث بن الخزرج وشهد بدرا وأحدا والخندق والحديبية وخيبر وعمرة القضاء والمشاهد كلها مع رسول الله صلى الله عليه وسلم إلا الفتح وما بعده لأنه كان قد قتل قبله وهو أحد الأمراء في غزوة مؤتة وهو خال النعمان بن بشير روى حماد بن زيد عن ثابت عن عبد الرحمن بن أبي ليلى أن عبد الله بن رواحة أتي النبي صلى الله عليه وسلم وهو يخطب فسمعه وهو يقول اجلسوا فجلس مكانه خارجا من المسجد حتى فرغ النبي صلى الله عليه وسلم من خطبته فبلغ ذلك النبي صلى الله عليه وسلم فقال له زادك الله حرصا على طواعية الله وطواعية رسوله وكان عبد الله أول خارج إلى الغزو وآخر قافل وكان من الشعراء الذين يناضلون عن رسول الله صلى الله عليه وسلم ومن شعره في النبي {{ص
أني تفرست فيك الخير أعرفه\\والله يعلم أن ما خانني البصر
أنت النبي ومن يحرم شفاعته\\يوم الحساب فقد أزرى به القدر
فثبت الله ما آتاك من حسن\\تثبيت موسى ونصرا كالذي نصروا}}
فقال النبي صلى الله عليه وسلم وأنت فثبتك الله يا ابن رواحة قال هشام بن عروة فثبته الله أحسن الثبات فقتل شهيدا وفتحت له أبواب الجنة فدخلها شهيدا قال أبو الدرداء أعوذ بالله أن يأتي علي يوم لا أذكر فيه عبد الله بن رواحة كان إذا لقيني مقبلا ضرب بين ثديي وإذا لقيني مدبرا ضرب بين كتفي ثم يقول يا عويمر اجلس فلنؤمن ساعة فنجلس فنذكر الله ما شاء ثم يقول يا عويمر هذه مجالس الإيمان أخبرنا عبيد الله بن أحمد بن علي بإسناده إلى يونس بن بكير عن ابن إسحاق حدثني عبد الله بن أبي بكر بن حزم قال سار عبد الله بن رواحة يعني إلى مؤتة وكان زيد بن أرقم يقيما في حجره فحمله على حقيبة رحله وخرج به غازيا إلى مؤتة فسمعه زيد من الليل يتمثل بأبياته التي قال

إذا أدنيتني وحملت رحليمسيرة أربع بعد الحساءفشأنك فانعمي وخلاك ذمولا أرجع إلى أهلي ورائيوجاء المؤمنون وغادرونيبأرض الشام مشهور الثواءوردّك كل ذي نسب قريبإلى الرحمن منقطع الإخاء هنالك لا أبالي طلع بعلولا نخل أسافلها رواء
فلما سمعه زيد بكى فخفقه بالدرة وقال ما عليك يا لكع أن يرزقني الله الشهادة وترجع بين شعبتي الرحل لزيد يقول عبد الله بن رواحة

يا زيد زيد اليعملات الذبلتطاول الليل هديت فانزل
يعني انزل فسق بالقوم قال وحدثنا ابن إسحاق حدثني محمد بن جعفر بن الزبير عن عروة بن الزبير قال أمر رسول الله صلى الله عليه وسلم على الناس يوم مؤتة زيد بن حارثة فإن أصيب فجعفر بن أبي طالب فإن أصيب جعفر فعبد الله بن رواحة فإن أصيب عبد الله فليرتض المسلمون رجلا فليجعلوه عليهم فتجهز الناس وتهيأوا للخروج فودع الناس أمراء رسول الله صلى الله عليه وسلم وسلموا عليهم فلما ودع الناس أمراء رسول الله صلى الله عليه وسلم وسلموا عليهم وودعوا عبد الله بن رواحة بكى قالوا ما يبكيك يا ابن رواحة فقال أما والله ما بي حب الدنيا ولا صبابة إليها ولكني سمعت رسول الله صلى الله عليه وسلم يقرأ وإن منكم إلا واردها كان على ربك حتما مقضيا فلست أدري كيف لي بالصدر بعد الورود فقال المسلمون صحبكم الله وردكم إلينا صالحين ورفع إليكم فقال ابن رواحة

لكنني أسأل الرحمن مغفرةوضربه ذات فرع يقذف الزبداأو طعنة بيدي حران مجهزةبحربة تنفذ الأحشاء والكبداحتى يقولوا إذا مروا على جدثييا أرشد الله من غاز وقد رشدا
ثم أتى عبد الله رسول الله صلى الله عليه وسلم فودعه ثم خرج القوم حتى نزلوا معان فبلغهم أن هرقل نزل بمآب في مائة ألف من الروم ومائة ألف من المستعربة فأقاموا بمعان يومين فقالوا نبعث إلى رسول الله صلى الله عليه وسلم فنخبره بكثرة عدونا فإما أن يمدنا وإما أن يأمرنا أمرا فشجعهم عبد الله بن رواحة فساروا وهم ثلاثة آلاف حتى لحقوا جموع الروم بقرية من قرى البلقاء يقال لها شراف ثم انحاز المسلمون إلى مؤتة وروى عبد السلام بن النعمان بن بشير أن جعفر بن أبي طالب حين قتل دعا الناس عبد الله بن رواحة وهو في جانب العسكر فتقدم فقاتل وقال يخاطب نفسه:

يا نفس إلا تقتلي تموتيهذا حياض الموت قد صليتوما تمنيت فقد لقيتإن تفعلي فعلهما هديت
وإن تأخرت فقد شقيت 
يعني زيدا وجعفرا ثم قال يا نفس إلى أي شئ تتوقين إلى فلانة امرأته فهي طالق وإلى فلان وفلان غلمان له فهم أحرار وإلى معجف حائط له فهو لله ولرسوله ثم قال يا نفس مالك تكرهين الجنة * أقسم بالله لتنزلنه * طائعة أو لتكرهنه فطالما قد كنت مطمئنه * هل أنت إلا نطفة في شنه * قد أجلب الناس وشدوا الرنة وروى مصعب بن شيبة قال لما نزل ابن رواحة للقتال طعن فاستقبل الدم بيده فدلك به وجهه ثم صرع بين الصفين فجعل يقول يا معشر المسلمين ذبوا عن لحم أخيكم فجعل المسلمون يحملون حتى يحوزونه فلم يزالوا كذلك حتى مات مكانه قال يونس ابن بكير وحدثنا ابن إسحاق قال لما أصيب القوم قال رسول الله صلى الله عليه وسلم فيما بلغني أخذ زيد بن حارثة الراية فقاتل بها حتى قتل شهيدا ثم أخذها جعفر بن أبي طالب فقاتل حتى قتل شهيدا ثم صمت رسول الله صلى الله عليه وسلم حتى تغيرت وجوه الأنصار وظنوا أنه قد كان في عبد الله بن رواحة ما يكرهون فقال ثم أخذها عبد الله بن رواحة فقاتل حتى قتل شهيدا ثم لقد رفعوا لي في الجنة على سرر من ذهب فرأيت في سرير عبد الله بن رواحة أزوارا عن سريري صاحبيه فقلت عم هذا فقيل لي مضيا وتردد عبد الله بعض التردد ثم مضى فقتل ولم يعقب وكانت مؤتة في جمادى سنة ثمان أخرجه الثلاثة'
WHERE id = 77
  AND content_ar LIKE '(ب د ع) عبد الله بن %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 77;

-- id=78  معاذ بن جبل
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 78;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'معاذ بن جبل بن عمرو بن أوس بن عائذ بن عدي بن كعب بن عمرو بن أدي بن سعد بن علي بن أسد بن ساردة بن يزيد بن جشم بن الخزرج الأنصاري الخزرجي ثم الجشمي وأدى الذي ينسب إليه هو أخو سلمة بن سعد القبيلة التي ينسب إليها من الأنصار وقد نسبه بعضهم في بني سلمة وقال ابن إسحاق إنما ادعته بنو سلمة لأنه كان أخا سهل ابن محمد بن الجد بن قيس لأمه وسهل من بني سلمة وقال الكلبي هو من بني أدي كما نسبناه أولا قال ولم يبق من بني أدي أحد وعدادهم في بني سلمة وآخر من بقي منهم عبد الرحمن بن معاذ مات في طاعون عمواس بالشام وقيل إنه مات قبل أبيه معاذ فعلى هذا يكون معاذ آخرهم وهو الصحيح وكان معاذ يكنى أبا عبد الرحمن وهو أحد السبعين الذين شهدوا العقبة من الأنصار وشهد بدرا وأحدا والمشاهد كلها مع رسول الله صلى الله عليه وسلم وآخى رسول الله صلى الله عليه وسلم بينه وبين عبد الله بن مسعود وكان عمره لما أسلم ثماني عشرة سنة أخبرنا عبد الوهاب بن هبة الله بإسناده عن عبد الله بن أحمد قال حدثني أبي حدثنا أبو معاوية عن الأعمش عن شقيق عن مسروق عن عبد الله بن عمرو قال قال رسول الله صلى الله عليه وسلم خذوا القرآن من أربعة من ابن مسعود وأبي بن كعب ومعاذ بن جبل وسالم مولى أبي حذيفة أخبرنا إسماعيل وغيره قالوا بإسنادهم عن محمد بن عيسى حدثنا سفيان بن وكيع حدثنا حميد بن عبد الرحمن عن داود العطار عن معمر عن قتادة عن أنس بن مالك قال قال رسول الله صلى الله عليه وسلم أرحم أمتي بأمتي أبو بكر وذكر الحديث وقال وأعلمهم بالحلال والحرام معاذ بن جبل أخبرنا عبد الله
ابن أبي نصر الخطيب قال حدثنا جعفر بن أحمد القاري حدثنا علي بن المحسن حدثنا أبو سعيد الحسن بن جعفر بن محمد السمسار حدثنا أبو شعيب الحراني حدثنا يحيى بن عبد الله البابلي حدثنا سلمة بن وردان قال سمعت أنس بن مالك قال أتاني معاذ بن جبل من عند رسول الله صلى الله عليه وسلم فقال من شهد أن لا إله إلا الله مخلصا بها قلبه دخل الجنة فذهبت إلى رسول الله صلى الله عليه وسلم فقلت يا رسول الله حدثني معاذ أنك قلت من شهد أن لا إله إلا الله مخلصا بها قلبه دخل الجنة قال صدق معاذ صدق معاذ صدق معاذ وروى سهل بن أبي خيثمة عن أبيه قال كان الذين يفتون على عهد رسول الله صلى الله عليه وسلم من المهاجرين عمر وعثمان وعلي ثلاثة من الأنصار أبي بن كعب ومعاذ بن جبل وزيد بن ثابت وقال جابر ابن عبد الله كان معاذ بن جبل من أحسن الناس وجها وأحسنهم خلقا وأسمحهم كفا فادان دينا كثيرا فلزمه غرماؤه حتى تغيب عنهم أياما في بيته فطلب غرماؤه من رسول الله صلى الله عليه وسلم أن يحضره فأرسل إليه فحضر ومعه غرماؤه فقالوا يا رسول الله خذ لنا حقنا فقال رسول الله صلى الله عليه وسلم رحم الله من تصدق عليه فتصدق عليه ناس وأبى آخرون فخلعه رسول الله من ماله فاقتسموه بينهم فأصابهم خمسة أسباع حقوقهم فقال لهم رسول الله صلى الله عليه وسلم ليس لكم إلا ذلك فأرسله رسول الله صلى الله عليه وسلم إلى اليمن وقال لعل الله يجبرك ويؤدي عنك دينك فلم يزل باليمن حتى توفي رسول الله صلى الله عليه وسلم وروى ثور بن يزيد قال كان معاذ إذا تهجد من الليل قال اللهم نامت العيون وغارت النجوم وأنت حي قيوم اللهم طلبي الجنة بطئ وهربي من النار ضعيف اللهم اجعل لي عندك هدي ترده إلى يوم القيامة إنك لا تخلف الميعاد ولما وقع الطاعون بالشام قال معاذ اللهم أدخل على آل معاذ نصيبهم من هذا فطعنت له امرأتان فماتتا ثم طعن ابنه عبد الرحمن فمات ثم طعن معاذ بن جبل فجعل يغشى عليه فإذا أفاق قال اللهم غمني غمك فوعزتك إنك لتعلم أني أحبك ثم يغشى عليه فإذا أفاق قال مثل ذلك وقال عمرو بن قيس إن معاذ بن جبل لما حضره الموت قال انظروا أصبحنا فقيل لم نصبح حتى أتي فقيل أصبحنا فقال أعوذ بالله من ليلة صباحها إلى النار مرحبا بالموت مرحبا زائر حبيب جاء على فاقة اللهم تعلم أني كنت أخافك وأنا اليوم أرجوك إني لم أكن أحب الدنيا وطول البقاء فيها لكرى الأنهار ولا 
لغرس الأشجار ولكن لظمأ الهواجر ومكابدة الساعات ومزاحمة العلماء بالركب عند حلق الذكر وقال الحسن لما حضر معاذ الموت جعل يبكي فقيل له أتبكي وأنت صاحب رسول الله صلى الله عليه وسلم وأنت وأنت فقال ما أبكي جزعا من الموت إن حل بي ولا دنيا تركتها بعدي ولكن إنما هي القبضتان فلا أدري من أي القبضتين أنا قيل كان معاذ ممن يكسر أصنام بني سلمة وقال النبي صلى الله عليه وسلم معاذ أمام العلماء يوم القيامة برتوة أو رتوتين وقال فروة الأشجعي عن ابن مسعود إن معاذ بن جبل كان أمة قانتا لله حنيفا ولم يك من المشركين فقلت له إنما قال الله إن إبراهيم كان أمة قانتا لله فأعاد قوله إن معاذا كان أمة قانتا لله الآية وقال ما الأمة وما القانت قلت الله ورسوله أعلم قال الأمة الذي يعلم الخير ويؤتم به والقانت المطيع لله عز وجل وكذلك كان معاذ معلما للخير مطيعا لله عز وجل ولرسوله روى عنه من الصحابة عمر وابنه عبد الله وأبو قتادة وعبد الله بن عمرو وأنس بن مالك وأبو أمامة الباهلي وأبو ليلى الأنصاري وغيرهم ومن التابعين جنادة بن أبي أمية وعبد الرحمن بن غنم وأبو إدريس الخولاني وأبو مسلم الخولاني وجبير بن نفير ومالك ابن يخامر وغيرهم وتوفي في طاعون عمواس سنة ثمان عشرة وقيل سبع عشرة والأول أصح وكان عمره ثمانيا وثلاثين سنة وقيل ثلاث وقيل أربع وثلاثون وقيل ثمان وعشرون سنة وهذا بعيد فإن من شهد العقبة وهي قبل الهجرة ومقام النبي صلى الله عليه وسلم بالمدينة عشر سنين وبعد وفاة النبي صلى الله عليه وسلم ثمان سنين فيكون من الهجرة إلى وفاته ثمان عشرة سنة فعلى هذا يكون له وقت العقبة عشر سنين وهو بعيد جدا والله أعلم'
WHERE id = 78
  AND content_ar LIKE '(ب د ع) معاذ بن جبل %'
  AND source_codes IS NULL;

COMMIT;

