BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'خالد بن زيد بن كليب بن ثعلبة بن عبد عوف بن غنم بن مالك بن النجار واسمه تيم الله بن ثعلبة بن عمرو بن الخزرج الأكبر أبو أيوب الأنصاري الخزرجي وأمه هند بنت سعيد بن عمرو بن امرئ القيس بن مالك بن ثعلبة بن كعب بن الخزرج بن الحارث بن الخزرج وهو مشهور بكنيته شهد العقبة وبدرا وأحدا والمشاهد كلها مع رسول الله صلى الله عليه وسلم قاله ابن عقبة وابن إسحاق وعروة وغيرهم ولما قدم رسول الله صلى الله عليه وسلم المدينة مهاجرا نزل عليه وأقام عنده حتى بنى حجره ومسجده وانتقل إليها وآخى رسول إله صلى الله عليه وسلم بينه وبين مصعب بن عمير أخبرنا عبيد الله ابن أحمد بن علي بإسناده إلى يونس بن بكير عن ابن إسحاق قال فأقام رسول الله صلى الله عليه وسلم بين ظهرانيهم خمسا يعني بني عمرو بن عوف وبنو عمرو يزعمون أنه أقام أكثر من ذلك وخرج رسول الله صلى الله عليه وسلم إلى المدينة فاعترضه بنو سالم بن عوف فقالوا يا رسول الله هلم إلى العدد والعدة والقوة أنزل بين أظهرنا فقال رسول الله صلى الله عليه وسلم خلوا سبيلها فإنها مأمورة ثم مر ببني بياضة فاعترضوه فقال مثل ذلك ثم مر ببني ساعدة فقالوا مثل ذلك فقال خلوا سبيلها فإنها مأمورة ثم مر بأخواله بني عدي بن النجار فقالوا هلم إلينا أخوالك فقال مثل ذلك فمر ببني مالك بن النجار فبركت على باب مسجده ثم التفتت ثم انبعثت ثم كرت إلى مبركها الذي انبعثت منه فبركت فيه ثم تحلحلت في مناخها ورزمت فنزل رسول الله
صلى الله عليه وسلم عنها فاحتمل أبو أيوب خالد بن زيد رحله فأدخله بيته وأمر رسول الله صلى الله عليه وسلم ببناء المسجد وأخبرنا أبو الفرج يحيى بن محمود الثقفي بإسناده إلى أبي بكر أحمد بن عمرو بن الضحاك حدثنا أبو كامل أخبرنا الليث بن سعد ح قال أحمد وحدثنا أبو بكر بن أبي شيبة أخبرنا يونس بن محمد أخبرنا الليث بن سعد عن يزيد بن أبي حبيب عن أبي الخير عن أبي رهم السماعي أن أبا أيوب حدثهم أن النبي صلى الله عليه وسلم نزل في بيته الأسفل وكنت في الغرفة فهريق ماء في الغرفة فقمت أنا وأم أيوب بقطيفة لنا نتتبع الماء شفقا أن يخلص إلى رسول الله صلى الله عليه وسلم فنزلت إلى رسول الله صلى الله عليه وسلم وأنا مشفق فقلت يا رسول إنه ليس ينبغي أن نكون من فوقك فانتقل إلى الغرفة فأمر رسول الله صلى الله عليه وسلم بمتاعه فنقل فقلت يا رسول الله كنت ترسل إلي بالطعام فأنظر فإذا رأيت أثر أصابعك وضعت فيه يدي حتى كان هذا الطعام الذي أرسلت به إلي فنظرت فلم أر أثر أصابعك فقال رسول الله صلى الله عليه وسلم أجل إن فيه بصلا فكرهت أن آكل من أجل الملك وأما أنتم فكلوا وقد روي أن الطعام كان فيه ثوم وهو الأكثر والله أعلم روى حبيب بن أبي ثابت عن محمد بن علي بن عبد الله بن عباس عن ابن عباس إن أبا أيوب أتاه ابن عباس فقال له يا أبا أيوب إني أريد أن أخرج لك عن مسكني كما خرجت لرسول الله صلى الله عليه وسلم عن مسكنك وأمر أهله فخرجوا وأعطاه كل شئ أغلق عليه بابه فلما كان خلافة علي قال ما حاجتك قال حاجتي عطائي وثمانية أعبد يعملون في أرضي وكان عطاؤه أربعة آلاف فأضعفها له خمس مرات فأعطاه عشرين ألفا وأربعين عبدا وكان أبو أيوب ممن شهد مع علي رضي الله عنهما حروبه كلها ولزم الجهاد وقال قال الله تعالى انفروا خفافا وثقالا فلا أجدني إلا خفيفا أو ثقيلا ولم يتخلف عن الجهاد إلا عاما واحدا فإنه استعمل على الجيش رجل شاب فقعد ذلك العام فجعل بعد ذلك يتلهف ويقول وما علي من استعمل علي روى عنه من الصحابة ابن عباس وابن عمر والبراء بن عازب وأبو أمامة وزيد بن خالد الجهني والمقدام بن معدي كرب وأنس بن مالك وجابر بن سمرة وعبد الله بن يزيد الخطمي ومن التابعين سعيد بن المسيب وعروة وسالم بن عبد الله وأبو سلمة وعطاء بن يسار وعطاء بن يزيد وغيرهم وتوفى أبو أيوب مجاهدا سنة خمسين وقيل سنة إحدى وخمسين وقيل سنة اثنتين وخمسين وهو 
الأكثر وكان في جيش وأمير ذلك الجيش يزيد بن معاوية فمرض أبو أيوب فعاده يزيد فدخل عليه يعوده فقال ما حاجتك قال حاجتي إذا أنامت فاركب ثم اسع في أرض العدو وما وجدت مساغا فادفني ثم ارجع فتوفي ففعل الجيش ذلك ودفنوه بالقرب من القسطنطينية وقبره بها يستسقون به وسنذكر طرفا من أخباره في كنيته إن شاء الله تعالى أخرجه الثلاثة'
WHERE id = 79
  AND content_ar LIKE '(ب د ع) خالد بن زيد %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 79;

-- id=80  أبو دجانة (سماك بن خرشة)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 80;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سماك ابن خرشة وقيل سماك بن أوس بن خرشة بن لوذان بن عبد ود بن زيد بن ثعلبة بن الخزرج بن ساعدة بن كعب بن الخزرج الأنصاري الساعدي أبو دجانة وهو مشهور بكنيته شهد بدرا وأحدا وجميع المشاهد مع رسول الله صلى الله عليه وسلم وأعطاه رسول الله سيفه يوم أحد وقال من يأخذ هذا السيف بحقه فأحجم القوم فقال أبو دجانة أنا آخذه بحقه فدفعه رسول الله صلى الله عليه وسلم إليه ففلق به هام المشركين وقال في ذلك

أنا الذي عاهدني خليليونحن بالسفح لدى النخيلأن لا أقوم الدهر في الكيولأضرب بسيف الله والرسول
أخبرنا أبو جعفر عبيد الله بن أحمد بن علي بإسناده عن يونس بن بكير عن ابن إسحاق قال حدثني حسين بن عبد الله بن عبيد الله بن عباس عن عكرمة عن ابن عباس قال لما رجع رسول الله صلى الله عليه وسلم من أحد أعطى فاطمة ابنته سيفه وقال يا بنية اغسلي عن هذا الدم وأعطاها علي رضي الله عنهما سيفه وقال وهذا فاغسلي عنه دمه فوالله لقد صدقني اليوم فقال رسول الله لئن كنت صدقت القتال لقد صدقه سهل بن حنيف وأبو دجانة وكان من الشجعان المشهورين بالشجاعة وكانت له عصابة حمراء يعلم بها في الحرب فلما كان يوم أحد أعلم بها واختال بين الصفين فقال رسول الله صلى الله عليه وسلم إن هذه مشية يبغضها الله عز وجل إلا في هذا المقام أخبرنا أبو الفرج يحيى بن محمود وأبو ياسر بن أبي حبة بإسنادهما إلى مسلم بن الحجاج قال حدثنا أبو بكر بن أبي شيبة أخبرنا عفان أخبرنا حماد بن

سلمة أخبرنا ثابت عن أنس أن رسول الله صلى الله عليه وسلم أخذ سيفا يوم أحد فقال من يأخذ هذا مني فبسطوا أيديهم كل إنسان منهم يقول أنا أنا قال فمن يأخذه بحقه فأحجم القوم فقال سماك أبو دجانة أنا آخذه بحقه فأخذه ففلق به هام المشركين وهو من فضلاء الصحابة وأكابرهم استشهد يوم اليمامة بعد ما أبلى فيها بلاء عظيما وكان لبني حنيفة باليمامة حديقة يقاتلون من ورائها فلم يقدر المسلمون على الدخول إليهم فأمرهم أبو دجانة أن يلقوه إليها ففعلوا فانكسرت رجله فقاتل على باب الحديقة وأزاح المشركين عنه ودخلها المسلمون وقتل يومئذ وقيل بل عاش حتى شهد صفين مع علي والأول أصح وأكثر وأما الحرز المنسوب إليه فإسناده ضعيف أخرجه الثلاثة ويرد في الكنى أكثر من هذا'
WHERE id = 80
  AND content_ar LIKE '(ب د ع) سماك ابن خرش%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 80;

-- id=81  قتادة بن النعمان
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 81;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'قتادة بن النعمان بن زيد بن عامر بن سواد بن ظفر بن الخزرج بن عمرو بن مالك بن الأوس الأنصاري الأوسي ثم الظفري يكنى أبا عمرو وقيل أبو عمر وقيل أبو عبد الله وهو أخو أبي سعيد الخدري لأمه شهد العقبة وبدرا وأحدا والمشاهد كلها مع النبي صلى الله عليه وسلم وأصيبت عينه يوم بدر وقيل يوم أحد وقيل يوم الخندق قال أبو عمر الأصح والله أعلم أن عين قتادة أصيبت يوم أحد فردها رسول الله صلى الله عليه وسلم فكانت أحسن عينيه أنبأنا أبو الربيع سليمان بن أبي البركات محمد بن محمد بن خميس العدل أنبأنا أبي حدثنا أبو نصر أحمد بن عبد الباقي بن طوق أنبأنا ابن المرجي أنبأنا أبو يعلى أنبأنا أبو عبد الرحمن الأزرقي حدثنا عبد العزيز بن عمران عن عبد الرحمن بن الحارث بن عبيد عن جده قال أصيبت عين أبي يوم أحد فبزق فيها النبي صلى الله عليه وسلم فكانت أحسن عينيه قال وأخبرنا أبو يعلى حدثنا يحيى بن عبد الحميد الحماني حدثنا عبد الرحمن بن سليمان بن الغسيل عن عاصم بن عمر بن قتادة عن أبيه عن قتادة بن النعمان أنه أصيبت عينه يوم بدر فسالت حدقته على وجنته فأرادوا أن يقطعوها فسألوا النبي صلى الله عليه وسلم فقال لا فدعا به فغمز حدقته براحته فكان لا يدري أي عينيه
أصيبت وأنبأنا أبو جعفر بن أحمد بإسناده عن يونس بن بكير عن محمد بن إسحاق عن عاصم بن عمر بن قتادة قال أصيبت عين قتادة يوم أحد حتى وقعت على وجنته فردها رسول الله صلى الله عليه وسلم فكانت أحسن عينيه وروى الأصمعي عن أبي معشر المدني قال وفد أبو بكر بن محمد بن عمرو بن حزم بديون أهل المدينة إلى عمر بن عبد العزيز رجلا من ولد قتادة بن النعمان فلما قدم عليه قال ممن الرجل فقال

أنا ابن الذي سالت على الخد عينهفردت بكف المصطفى أحسن الردفعادت كما كانت لأول أمرهافيا حسن ما عين ويا حسن مارد
فقال عمر بن عبد العزيز

تلك المكارم لا قعبان من لبنشيبا بماء فعادا بعد أبوالا
وكان قتادة من فضلاء الصحابة وكانت معه راية بني ظفر يوم الفتح وروى أبو سلمة عن أبي سعيد الخدري أن النبي صلى الله عليه وسلم خرج ليلة لصلاة العشاء وهاجت الظلمة والسماء وبرقت برقه فرأى رسول الله صلى الله عليه وسلم قتادة بن النعمان فقال قتادة قال نعم يا رسول الله علمت أن شاهد الصلاة الليلة قليل فأحببت أن أشهدها فقال له إذا انصرفت فأتني فلما انصرف أعطاه عرجونا فقال خذ هذا يضئ أمامك عشرا وخلفك عشرا وقتادة هذا هو جد عاصم بن عمر ابن قتادة المحدث النسابة أكثر محمد بن إسحاق الرواية عنه روى أبو قتادة عن النبي صلى الله عليه وسلم روى عنه أبو سعيد الخدري وغيره أنبأنا إسماعيل ابن علي بن عبيد وإبراهيم بن محمد بن مهران وغيرهما بإسنادهم إلى أبي عيسى محمد بن عيسى قال حدثنا محمد بن يحيى حدثنا إسحاق بن محمد الهروي حدثنا إسماعيل بن جعفر عن عمارة بن غزية عن عاصم بن عمر بن قتادة عن محمود بن لبيد عن قتادة بن النعمان أن رسول الله صلى الله عليه وسلم قال إذا أحب الله العبد حماه الدنيا كما يظل أحدكم يحمي سقيمه الماء وتوفي قتادة بن النعمان سنة ثلاث وعشرين وهو ابن خمس وستين سنة وصلى عليه عمر بن الخطاب ونزل في قبره أبو سعيد الخدري ومحمد بن مسلمة أخرجه الثلاثة إلا أن أبا نعيم قال سقطت حدقتاه فردهما رسول الله صلى الله عليه وسلم وهذا لا يصح إنما سقطت إحدى عينيه فردها رسول الله صلى الله عليه وسلم كما ذكرنا والله أعلم'
WHERE id = 81
  AND content_ar LIKE '(ب د ع) قتادة بن الن%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 81;

-- id=82  الحباب بن المنذر
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 82;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'حباب بن المنذر بن الجموح بن زيد بن حرام بن كعب بن غنم بن كعب ابن سلمة الأنصاري الخزرجي السلمي يكنى أبا عمر وقيل أبا عمرو وشهد بدرا وهو ابن ثلاث وثلاثين سنة هكذا قال الواقدي وغيره وقالوا كلهم أنه شهد بدرا إلا ابن إسحاق من رواية سلمة عنه والصحيح أنه شهدها وكان يقال له ذو الرأي لما أخبرنا عبيد الله بن أحمد بن علي البغدادي بإسناده إلى ابن إسحاق قال حدثني يزيد بن رومان عن عروة بن الزبير ح قال ابن إسحاق وحدثني الزهري ومحمد بن يحيى ابن حبان وعاصم بن عمر بن قتادة وعبد الله بن أبي بكر وغيرهم من علمائنا في ما ذكرت من يوم بدر قالوا وسار رسول الله صلى الله عليه وسلم يبادرهم يعني قريشا إليه يعني إلى الماء فلما جاء أدنى ماء من بدر نزل عليه فقال الحباب بن المنذر بن الجموح

يا رسول الله منزل أنزلكه الله ليس لنا أن نتعداه ولا نقصر عنه أم هو الرأي والحرب والمكيدة فقال رسول الله صلى الله عليه وسلم بل هو الرأي والحرب والمكيدة قال الحباب يا رسول الله ليس بمنزل ولكن انهض حتى تجعل القلب كلها من وراء ظهرك ثم غور كل قليب بها إلا قليبا واحدا ثم احفر عليه حوضا فنقاتل القوم ونشرب ولا يشربون حتى يحكم الله بيننا وبينهم فقال رسول الله صلى الله عليه وسلم قد أشرت بالرأي ففعل ذلك وشهد الحباب المشاهد كلها مع رسول الله صلى الله عليه وسلم وهو القائل يوم سقيفة بني ساعدة عند بيعة أبي بكر أنا جذيلها المحكك وعذيقها المرجب منا أمير ومنكم أمير وتوفي الحباب في خلافة عمر بن الخطاب روى عنه أبو الطفيل عامر بن واثلة أخرجه الثلاثة * قوله جذيلها هو تصغير جذل أراد العود الذي ينصب للإبل الجربى لتحتك به أي أنا ممن يستشفى برأيه كما تستشفى الإبل الجربى بالاحتكاك وعذيقها تصغير عذق بالفتح وهو النخلة والمرجب هو أن تدعم النخلة الكريمة ببناء من حجارة أو خشب إذا خيف عليها لطولها وكثرة حملها أن تقع يقال رجبتها فهي مرجبة * يحيى بن حبان بفتح الحاء المهملة والباء الموحدة وآخره نون'
WHERE id = 82
  AND content_ar LIKE '(ب د ع) حباب بن المن%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 82;


