BEGIN;

UPDATE public.stories
SET source_codes = 'ب ع س',
    content_ar = 'قيس بن مخلد بن ثعلبة بن صخر بن حبيب بن الحارث بن ثعلبة بن مازن ابن النجار الأنصاري الخزرجي المازني شهد بدرا قاله ابن شهاب وابن إسحاق وقتل يوم أحد شهيدا أخرجه أبو عمر وأبو نعيم وأبو موسى قلت قد أخرج أبو موسى هذا قيسا في موضعين من كتابه فقال في أحدهما قيس بن مخلد الأنصاري وروى بإسناده عن ابن شهاب في تسمية من شهد بدرا من الأنصار من الخزرج من بني ثعلبة ابن مازن بن النجار قيس بن مخلد بن ثعلبة بن صخر بن حبيب بن الحارث بن ثعلبة وقال في الموضع الثاني قيس بن مخلد بن ثعلبة بن مازن النجاري شهد بدرا وقتل يوم أحد ولا شك أنه رأى في هذه ثعلبة بن مازن وإنه قتل يوم أحد وأنه رأى في تلك بين ثعلبة وبين مازن عدة آباء ولم يذكر فيه أنه قتل بأحد فظنهما اثنين وهما واحد لا شبهة فيه وقد سقط من هذا النسب عدة آباء والصواب هو النسب الذي ذكرناه أول الترجمة والله أعلم'
WHERE id = 192
  AND content_ar LIKE '(ب ع س) قيس بن مخلد %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 192;

-- id=193  عمارة بن حزم
SELECT id, source_codes, left(content_ar, 60) AS content_preview
