    content_ar = 'ربعي بن أبي ربعي بدري قال أبو نعيم هو ابن رافع الأنصاري وروى بإسناده عن ابن شهاب في تسمية من شهد بدرا من الأوس

من بني العجلان ربعي بن رافع وروى يونس بن بكير عن ابن إسحاق فيمن شهد بدرا من الأوس ثم من بني العجلان ربعي بن رافع بن الحارث بن زيد بن حارثة بن الجد بن العجلان أخرجه أبو نعيم وأبو موسى قلت قد أخرج أبو نعيم وتبعه أبو موسى هذه الترجمة والتي قبلها ولم ينسبا الأول بل قالا ربعي بن رافع وذكرا عن عبيد الله بن أبي رافع أنه شهد مع علي وقالا إنه بدري ولو نسبا ذلك لعلما أنهما واحد وأن أبا ربعي اسمه رافع وأنه المذكور في الترجمة الأولى وذكرا في الأولى اسم أبيه وفي الثانية كنيته فلو ركبا منهما ترجمة واحدة لكانت الصواب ومن وقف على نسبه الذي أخرجناه في الأولى عن أبي عمرو بن الكلبي علم أنهما واحد وأنه بدري'
WHERE id = 195
  AND content_ar LIKE '(ع س) ربعي بن أبي رب%'
