    content_ar = 'معتب بن قشير وقيل معتب بن بشير ابن مليل بن زيد بن العطاف بن ضبيعة بن زيد بن مالك بن عوف بن عمرو بن عوف

ابن مالك بن الأوس الأنصاري الأوسي شهد العقبة وبدرا وأحدا أخبرنا عبيد الله بن أحمد بإسناده عن يونس عن ابن إسحاق فيمن شهد بدرا من الأنصار من بني ضبيعة بن زيد ومعتب ابن فلان بن مليل لا عقب له كذا في رواية يونس لم يسم أباه ورواه البكائي وسلمة عن ابن إسحاق فقالا معتب بن قشير وبهذا الإسناد عن ابن إسحاق قال حدثني يحيى بن عباد بن عبد الله بن الزبير عن أبيه عن جده عبد الله بن الزبير عن الزبير أنه قال والله لكأني أسمع قول معتب بن قشير وإن النعاس ليغشاني ما أسمعها منه إلا كالحلم وهو يقول لو كان لنا من الأمر شئ ما قتلنا هاهنا أخرجه الثلاثة * معتب بضم الميم وفتح العين المهملة وتشديد التاء فوقها نقطتان'
WHERE id = 196
  AND content_ar LIKE '(ب د ع) معتب بن قشير%'
