-- id=200  نصر بن الحارث
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 200;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب ع س',
    content_ar = 'نصر بن الحارث بن عبيد بن رزاح بن كعب وكعب هو ظفر

الأنصاري الأوسي الظفري وقيل ابن عبد رزاح وقال أبو موسى ابن عبد الله والأولان أصح وأكثر يكنى أبا الحارث شهد بدرا وكان أبوه الحارث ممن صحب النبي صلى الله عليه وسلم كذا سماه أكثر أهل السير والأنساب نصر بن الحارث وقال ابن سعد روى عن محمد بن إسحاق نمير بن الحارث قال ابن سعد وهذا غلط من قبل من رواه عنه قيل إن الذي رواه عنه إبراهيم بن سعد الزهري أخرجه أبو نعيم وأبو موسى قلت قد جعل ابن سعد الغلط فيه من إبراهيم بن سعد وقد رواه يونس بن بكير وسلمة بن الفضل عن ابن إسحاق نمير أيضا ورواه ابن هشام عن البكائي عن ابن إسحاق فقال نضر بالضاد المعجمة وكذلك ذكره ابن ماكولا بالضاد المعجمة وقال ذكره ابن القداح وقال قتل بالقادسية'
WHERE id = 200
  AND content_ar LIKE '(ب ع س) نصر بن الحار%'
  AND source_codes IS NULL;

