BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'ذو الشمالين واسمه عمير بن عبد عمرو بن نضلة بن عمرو بن غبشان بن سليم بن مالك بن أفصى ابن حارثة بن عمرو بن عامر كذا نسبه أبو عمر جعله من بني مالك بن أفصى أخي خزاعة وخالفه غيره فقال غبشان واسمه الحارث بن عبد عمرو بن عمرو بن بوي بن ملكان ابن أفصى حليف بني زهرة فجعله من ولد ملكان بن أفصى وهو أخو خزاعة وأسلم وشهد بدرا وقتل بها قتله أسامة الجشمي وقال ابن إسحاق ذو الشمالين بن عبد عمرو ابن نضلة بن غبشان وقال الزهري هو خزاعي وهذا ليس بذي اليدين الذي ذكر في

السهو في الصلاة لأن ذا الشمالين قتل ببدر والسهو في الصلاة شهده أبو هريرة وكان إسلامه بعد بدر بسنين ويرد الكلام عليه في ذي اليدين إن شاء الله تعالى أخرجه الثلاثة'
WHERE id = 202
  AND content_ar LIKE '(ب د ع) ذو الشمالين %'
  AND source_codes IS NULL;

