-- id=219  خباب مولى عتبة بن غزوان
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 219;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'خباب مولى عتبة بن غزوان شهد بدرا وما بعدها هو ومولاه عتبة مع رسول الله صلى الله عليه وسلم وكان حليفا لبني نوفل بن عبد مناف وكنيته أبو يحيى وليست له رواية أخبرنا أبو جعفر عبيد الله بن أحمد بن علي بإسناده إلى يونس بن بكير عن ابن إسحاق في تسمية من شهد بدرا مع رسول الله صلى الله عليه وسلم من قريش قال ومن بني نوفل بن عبد مناف عتبة بن غزوان وخباب مولى عتبة بن غزوان رجلان وتوفي بالمدينة سنة سبع عشرة وهو ابن خمسين سنة وصلى عليه عمر بن الخطاب رضي الله عنهما ولم يعقب أخرجه الثلاثة
(د ع خباب) والد عطاء أدرك النبي صلى الله عليه وسلم وروى عن أبي بكر الصديق قاله ابن منده وقال أبو نعيم قيل إنه أدرك النبي صلى الله عليه وسلم فيما ذكره بعض المتأخرين يعني ابن منده ولا تصح صحبته روى حديثه محمد بن عطاء بن خباب عن أبيه عن جده قال كنت جالسا عند أبي بكر الصديق رضي الله عنه فرأى طائرا فقال طوبى لك فقلت تقول هذا وأنت صديق رسول الله صلى الله عليه وسلم أخرجه ابن منده وأبو نعيم'
WHERE id = 219
  AND content_ar LIKE '(ب د ع) خباب مولى عت%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 219;

-- id=220  طفيل بن مالك بن خنساء
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 220;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'طفيل بن مالك بن خنساء شهد بدرا له ذكر ولا تعرف له رواية قال أبو نعيم بإسناده عن موسى بن عقبة عن ابن شهاب في تسمية من شهد بدرا من الأنصار من الخزرج الطفيل بن مالك بن خنساء وأخبرنا أبو جعفر عبيد الله بن أحمد بن علي بإسناده إلى يونس بن بكبر عن ابن إسحاق في تسمية من شهد بدرا من الأنصار

ومن بني عبيد بن عدي بن غنم بن كعب ثم من بني خنساء بن سنان بن عبيد والطفيل بن مالك بن خنساء وقال أبو عمر الطفيل بن مالك بن النعمان بن خنساء وقيل طفيل بن النعمان بن خنساء الأنصاري السلمي من بني سلمة شهد العقبة وبدرا وأحدا وجرح بأحد ثلاث عشر جراحة ولم يمت منها وقتل يوم الخندق شهيدا قتله وحشي بن حرب وذكر موسى بن عقبة في البدريين طفيل بن النعمان بن خنساء وطفيل بن مالك بن خنساء رجلين وكلام أبي عمر يدل على أنه ظنهما واحدا ويرد الكلام عليه في طفيل بن النعمان أن شاء الله تعالى أخرجه الثلاثة'
WHERE id = 220
  AND content_ar LIKE '(ب د ع) طفيل بن مالك%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 220;

-- id=221  مالك بن الدخشم
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 221;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'مالك بن الدخشم بن مالك بن غنم بن عوف بن عمرو بن عوف وقيل مالك بن الدخشم بن مالك بن الدخشم بن مرضحة بن غنم شهد العقبة في قول ابن إسحاق وموسى بن عقبة والواقدي وقال أبو معشر لم يشهد مالك العقبة وقد روى عن الواقدي أيضا أنه لم يشهدها وشهد بدرا في قول الجميع وهو الذي أسر يوم بدر سهيل بن عمرو وكان يتهم بالنفاق وهو الذي قال فيه عتيان بن مالك لرسول الله صلى الله عليه وسلم أنه منافق فقال رسول الله صلى الله عليه وسلم أليس يشهد أن لا إله إلا الله فقال بلى ولا شهادة له فقال رسول الله صلى الله عليه وسلم أليس يصلي قال بلى ولا صلاة له فقال رسول الله صلى الله عليه وسلم أولئك الذين نهاني

الله عنهم ولا يصح عنه النفاق وقد ظهر من حسن إسلامه ما يمنع من اتهامه وهو الذي أرسله رسول الله صلى الله عليه وسلم فأحرق مسجد الضرار هو ومعن بن عدي أخرجه الثلاثة'
WHERE id = 221
