-- id=238  عبد الله بن عمرو بن حرام
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 238;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبد الله ابن عمرو بن حرام بن ثعلبة بن حرام بن كعب بن غنم بن سلمة بن سعد بن علي بن أسد ابن ساردة بن يزيد بن جشم الخزرج الأنصاري الخزرجي السلمي يكنى أبا جابر بابنه جابر بن عبد الله كان عبد الله عقبيا بدريا نقيبا كان نقيب بني سلمة هو والبراء بن معرور ذكره عروة وابن شهاب وموسى بن عقبة وابن إسحاق وغيرهم فيمن شهد بدرا وأحدا وقتل يوم أحد أخبرنا محمد بن محمد بن سرايا بن علي أخبرنا عبد الأول
ابن عيسى أخبرنا أبو منصور بن أبي عاصم الفضيل بن يحيى الفضيلي حدثنا عبد الرحمن بن أبي شريح أخبرنا أبو القاسم المنيعي حدثنا علي بن مسلم حدثنا أبو داود حدثنا شعبة قال سمعت محمد بن المنكدر قال سمعت جابر بن عبد الله قال قتل أبي يوم أحد فجئت إليه وقد مثل به وهو مغطى الوجه فجعلت أبكي وجعل القوم ينهونني ورسول الله صلى الله عليه وسلم لا ينهاني قال فجعلت فاطمة بنت عمرو يعني عمته تبكي فقال رسول الله صلى الله عليه وسلم تبكيه أو لا تبكيه ما زالت الملائكة تظله بأجنحتها حتى رفعتموه أخبرنا أبو محمد عبد الله بن علي بن سويدة التكريتي أخبرنا عبد الله بن الحسين بن الفرخان إجازة أخبرنا أبو الحسن علي بن أحمد الواحدي أخبرنا أبو بكر أحمد الواحدي أخبرنا أبو بكر أحمد بن محمد بن الحارث أخبرنا أبو الشيخ الحافظ أخبرنا أحمد بن الحسين الحذاء أخبرنا علي بن المديني حدثنا موسى بن إبراهيم بن بشير بن الفاكه الأنصاري أنه سمع طلحة بن خراش الأنصاري قال سمعت جابر بن عبد الله قال نظر إلى رسول الله صلى الله عليه وسلم فقال مالي أراك منكسرا مهتما قلت يا رسول الله قتل أبي وترك دينا وعيالا فقال ألا أخبرك ما كلم الله أحدا قط إلا من وراء حجاب وإنه كلم أباك كفاحا فقال يا عبدي سلني أعطك قال أسألك أن تردني إلى الدنيا فأقتل فيك ثانية قال إنه قد سبق مني أنهم لا يردون إليها ولا يرجعون قال يا رب أبلغ من ورائي فأنزل الله تعالى ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء الآية ولما أراد أن يخرج إلى أحد دعا ابنه جابرا فقال يا بني إني لا أراني إلا مقتولا في أول من يقتل وإني والله لا أدع بعدي أحدا أعز علي منك غير نفس رسول الله صلى الله عليه وسلم وإن علي دينا فاقض عني ديني واستوص بأخواتك خيرا قال فأصبحنا فكان أول قتيل جدعوا أنفه وأذنيه ودفن هو وعمرو بن الجموح في قبر واحد قال النبي صلى الله عليه وسلم ادفنوهما في قبر واحد فإنهما كان متصافيين متصادفين في الدنيا وكان عمرو أيضا زوج أخت عبد الله واسمها هند بنت عمرو بن حرام قال جابر حفرت لأبي قبرا بعد ستة أشهر فحولته إليه فما أنكرت منه شيئا إلا شعرات من لحيته كانت مستها الأرض أخبرنا أبو الحرم مكي بن زياد بن شبه المقري النحوي بإسناده إلى يحيى بن يحيى عن مالك عن عبد الرحمن بن عبد الله بن عبد الرحمن بن أبي صعصعة أنه بلغه أن عمرو بن الجموح وعبد الله بن عمرو بن حرام الأنصاريين ثم السلميين كانا قد حفر السيل عن قبرهما وكان 
قبرهما مما يلي السيل وكانا في قبر واحد وكانا ممن استشهد يوم أحد فحفرا عنهما ليغيرا من مكانهما فوجدا لم يتغيرا كأنما ماتا بالأمس وكان أحدهما قد وضع يده على جرحه فدفن وهو كذلك فأميطت يده عن جرحه ثم أرسلت فرجعت كما كانت وكان بين يوم أحد وبين يوم حفر عنهما ست وأربعون سنة وكان الذي قتل عبد الله أسامة الأعور بن عبيد وقيل بل قتله سفيان بن عبد شمس أبو أبي الأعور السلمي أخرجه الثلاثة رضي الله عنه وأرضاه'
WHERE id = 238
  AND content_ar LIKE '(ب د ع) عبد الله ابن%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 238;

-- id=239  رافع بن مالك بن العجلان
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 239;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'رافع بن مالك بن العجلان بن عمرو بن عامر بن زريق بن عامر بن عبد حارثة بن مالك بن غضب بن جشم بن الخزرج الأنصاري الخزرجي الزرقي يكنى أبا مالك وقيل يكنى أبا رفاعة نقيب عقبي بدري شهد العقبة الأولى والثانية وكان نقيب بني زريق قال موسى بن عقبة إنه شهد بدرا ولم يذكره ابن إسحاق فيهم وذكر فيهم ابنيه رفاعة وخلادا إلا أنهما ليسا بنقيبين وقال سعد بن عبد الحميد بن جعفر رافع بن مالك أحد الستة النقباء وأحد الاثني عشر وأحد السبعين قتل يوم أحد شهيدا قال أبو عمر النقباء الستة قتلوا كلهم وكان هو ومعاذ بن عفراء أول خزرجيين أسلما قاله أبو نعيم وقال قال ابن إسحاق وان رافعا أول من قدم المدينة بسورة يوسف روى عنه ابنه رفاعة بن رافع أن جبريل أتي النبي صلى الله عليه وسلم فقال يا رسول الله كيف أهل بدر فيكم قال هم أفاضلنا قال جبريل فكذلك من شهدها من الملائكة أخبرنا أبو جعفر بن السمين بإسناده إلى يونس بن بكير عن ابن إسحاق قال أخبرني عاصم بن عمر بن قتادة عن أشياخ من قومه قال لما لقي رسول الله صلى الله عليه وسلم النفر الستة من الأنصار من الخزرج بمكة وجلسوا معه فدعاهم إلى الله عز وجل وعرض عليهم الإسلام وتلا عليهم القرآن وذكرهم وقال كان من زريق بن عامر رافع بن مالك بن الجعلان بن عمرو بن عامر بن زريق بن عامر بن عبد حارثة بن ثعلبة فلما قدموا المدينة ذكروا لقومهم الإسلام ودعوهم إليه ففشا فيهم فلم تبق دار من دور الأنصار إلا وفيها ذكر من رسول الله صلى الله عليه وسلم حتى إذا كان العام المقبل وافى الموسم من الأنصار اثنا عشر رجلا لقوا رسول الله صلى الله عليه وسلم بالعقبة وهى العقبة الأولى فبايعوه على بيعة النساء وذلك قبل أن تفرض عليهم الحرب ثم كانت العقبة الثانية وشهدها سبعون من الأنصار وبايعهم رسول الله على حرب الأحمر والأسود واشترط على القوم لربه وجعل لهم على الوفاء بذلك الجنة وكان فيهم رافع بن مالك نقيبا وقيل أنه هاجر إلى النبي صلى الله عليه وسلم وأقام معه بمكة فلما نزلت سورة طه كتبها ثم أقبل بها إلى المدينة فقرأها على بني زريق قاله ابن إسحاق وقال ابن منده عن ابن إسحاق أن رافعا شهد بدرا

وقال أبو عمر عن ابن إسحاق إنه لم يشهد ولا شك أن أبا عمر قد نقل من مغازي البكائي أو سلمة بن الفضل عن ابن إسحاق فإنه لم يذكر رافعا في هاتين الروايتين فيمن شهد بدرا ورواه يونس بن بكير عن ابن إسحاق أخبرنا عبيد الله بن أحمد بن علي بإسناده عن يونس بن بكير عن ابن إسحاق فيمن شهد بدرا من الأنصار قال ومن بني العجلان ابن عمرو بن عامر بن زريق رافع بن مالك بن العجلان وذكر غيره والله أعلم أخرجه الثلاثة'
WHERE id = 239
  AND content_ar LIKE '(ب د ع) رافع بن مالك%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 239;

-- id=240  زياد بن السكن
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 240;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'زياد ابن السكن بن رافع بن امرئ القيس بن زيد بن عبد الأشهل الأنصاري الأوسي الأشهلي يجتمع هو وسعد بن معاذ في امرئ القيس قتل يوم أحد شهيدا أخبرنا أبو القاسم أسعد بن يحيى بن أسعد بن بوش الأزجي إذنا أخبرنا أبو غالب بن البنا أخبرنا أبو الحسين محمد بن أحمد بن محمد بن الآبنوسي أخبرنا أبو إسحاق إبراهيم بن محمد بن الفتح الحلي المصيصي أخبرنا أبو يوسف محمد بن سفيان بن موسى الصفار المصيصي أخبرنا أبو عثمان سعيد بن رحمة بن نعيم الأصبحي قال سمعت ابن المبارك عن محمد بن إسحاق عن الحصين بن عبد الرحمن بن عمرو بن سعد بن معاذ عن محمود بن عمرو بن يزيد بن السكن أن رسول الله صلى الله عليه وسلم لما لحمه القتال يوم أحد وخلص إليه ودنا منه الأعداء ذب عنه مصعب بن عمير حتى قتل وأبو دجانة سماك بن خرشة حتى كثرت فيه الجراح وأصيب وجه رسول الله صلى الله عليه وسلم وثلمت

رباعيته وكملت شفته وأصيبت وجنته وكان رسول الله صلى الله عليه وسلم قد ظاهر بين درعين فقال رسول الله صلى الله عليه وسلم من يبيع لنا نفسه فوثب فئة من الأنصار خمسة منهم زياد بن السكن فقاتلوا حتى كان آخرهم زياد بن السكن فقاتل حتى أثبت ثم ثاب إليه ناس من المسلمين فقاتلوا عنه حتى أجهضوا عنه العدو فقال رسول الله صلى الله عليه وسلم لزياد بن السكن ادن مني وقد أثبتته الجراحة فوسده رسول الله صلى الله عليه وسلم قدمه حتى مات عليها ورواه الطبري عن محمد بن حميد عن سلمة عن ابن إسحاق عن الحصين بن عبد الرحمن عن محمود بن عمرو بن يزيد بن السكن قال فقام زياد بن السكن في نفر خمسة من الأنصار وبعض الناس يقول إنما هو عمارة بن زياد بن السكن على ما نذكره إن شاء الله تعالى وأخبرنا أبو جعفر عبيد الله بن أحمد بإسناده عن يونس بن بكير عن ابن إسحاق عن الحصين عن محمود فقال زياد بن السكن أخرجه الثلاثة'
WHERE id = 240
  AND content_ar LIKE '(ب د ع) زياد ابن الس%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 240;


-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 30/31 (8 صفوف)

-- id=241  أنس بن النضر
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 241;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'أنس بن النضر بن ضمضم وقد تقدم نسبه في أنس بن مالك وهذا أنس هو عم أنس بن مالك خادم النبي صلى الله عليه وسلم قتل يوم أحد شهيدا أخبرنا أبو عبد الله محمد بن محمد بن سرايا بن علي البلدي وغير واحد بإسنادهم عن محمد بن إسماعيل البخاري أخبرنا عمرو بن زرارة أخبرنا زياد حدثني حميد الطويل عن أنس بن مالك عن عمه أنس بن النضر وبه سمي أنس غاب عمي عن قتال بدر فقال يا رسول الله غبت عن أول قتال قاتلت فيه

المشركين والله لئن أشهدني الله قتال المشركين ليرين الله ما أصنع فلما كان يوم أحد انكشف المسلمون فقال اللهم إني أعتذر إليك مما صنع هؤلاء يعني المسلمين وأبرأ إليك مما جاء به هؤلاء يعني المشركين ثم تقدم فاستقبله سعد بن معاذ فقال أي سعد هذه الجنة ورب أنس أجد ريحها دون أحد قال سعد بن معاذ فما استطعت ما صنع فقاتل قال أنس فوجدنا به بضعا وثمانين ما بين ضربة بسيف أو طعنة برمح أو رمية بسهم ووجدناه قد قتل ومثل به المشركون فما عرفته أخته الربيع بنت النضر إلا ببنانه قال أنس كنا نرى أو نظن أن هذه الآية نزلت فيه وفي أشباهه من المؤمنين رجال صدقوا ما عاهدوا الله عليه الآية قال وأخبرنا محمد بن إسماعيل أخبرنا محمد ابن سلام أخبرنا الفزاري عن حميد عن أنس قال كسرت الربيع وهي عمة أنس ابن مالك ثنية جارية من الأنصار فطلب القوم القصاص فأتوا النبي صلى الله عليه وسلم فأمر النبي بالقصاص فقال أنس بن النضر عم أنس بن مالك لا والله لا تكسر ثنيتها يا رسول الله فقال رسول الله صلى الله عليه وسلم كتاب الله القصاص فرضي القوم وقبلوا الأرش فقال رسول الله صلى الله عليه وسلم إن من عباد الله من لو أقسم على الله لأبره أخرجه الثلاثة * سلام بالتخفيف والربيع بضم الراء وفتح الباء الموحدة وتشديد الياء تحتها نقطتان'
WHERE id = 241
  AND content_ar LIKE '(ب د ع) أنس بن النضر%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 241;

-- id=242  عبادة بن الخشخاش
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 242;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عبادة بن الخشخاش العنبري قاله ابن منده ولم يذكره غيره أنه عنبري وهو ابن الخشخاش بن عمرو بن زمزمة بن عمرو بن عمارة بن مالك بن عمرو بن بثيرة بن مشنوء بن العشر بن تميم بن عوذ بن مناة بن تيم بن إراشة بن عامر بن عبيلة بن قشميل بن فراز بن بلي البلوي لم يختلفوا أنه من بلي إلا ابن منده فإنه جعله عنبريا قالوا وهو ابن عم المجذر بن زياد وأخوه لأمه وهو حليف بني سالم من بني عوف من الأنصار شهد بدرا وقتل يوم أحد شهيدا وقد روى ابن منده بإسناده إلى يونس بن بكير عن ابن إسحاق قال قتل يوم أحد من المسلمين من بني عوف بن الخزرج ثم من بني سالم عبادة بن الخشخاش ودفن هو والنعمان بن مالك والمجذر بن زياد في قبر واحد أخرجه الثلاثة قلت وقيل فيه عباد بفتح العين وبغير هاء في آخره وقيل الخشخاش بخاءين وشينين معجمات وقيل بحاءين وسينين مهملات وقول ابن منده أنه عنبري وهم منه وأظنه رأى أن الخشخاش العنبري له صحبة فظن أن هذا ابن له ثم هو نقضه على نفسه بقوله قتل بأحد من الأنصار من بني سالم عبادة ومع أنه قد نسبه إلى سالم ثم إلى الخزرج ولم ير في نسبه العنبر كيف قال إنه عنبري وقد ذكره ابن ماكولا فقال عبادة بن الخشخاش بن عمرو بن زمزمة له صحبة وشهد بدرا وقتل يوم أحد قاله ابن إسحاق وأبو معشر يعني بالخاءين والشينين المعجمات وقال الواقدي هو عبدة بن الحسحاس بالحاءين والسينين المهملات وهو ابن عم المجذر بن زياد وأخوه لأمه قتل يوم أحد وهذا جميعه يرد قول ابن منده وسياق النسب أول الترجمة عن ابن الكلبي يقوي ما قلناه والله أعلم'
WHERE id = 242
  AND content_ar LIKE '(ب د ع) عبادة بن الخ%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 242;

-- id=243  إياس بن أوس بن عتيك
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 243;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'إياس بن أوس بن عتيك بن عمرو الأنصاري الأشهلي نسبه هكذا ابن منده وأبو نعيم وأما أبو عمر فإنه قال إياس بن أوس بن عتيك بن عمرو بن عبد الأعلم بن عامر بن زعورا بن جشم بن الحارث بن الخزرج بن عمرو وهو السيت بن مالك بن الأوس وزعورا بن جشم أخو عبد الأشهل قال ويقال فيه الأنصاري الأشهلي وهذا أصح وكذلك نسبه ابن الكلبي وابن حبيب إلا أن أبا عمر قال عبد الأعلى وقيل عبد الأعلم والصحيح عبد الأعلم استشهد يوم أحد قاله ابن إسحاق من رواية يونس والبكائي وسلمة بن الفضل وجعله ابن إسحاق من بني عبد الأشهل وتناقض قوله فيه لأنه قال في تسمية من استشهد يوم أحد قال ومن بني عبد الأشهل وذكر جماعة منهم ومن حلفائهم ثم قال ومن أهل راتج وهو حصن بالمدينة فهذا يدل على أن أهل راتج غير بني عبد الأشهل فذكر إياس بن أوس بن عتيك بن عمرو بن عبد الأعلم بن عامر بن زعورا بن جشم بن عبد الأشهل فجعله من أهل راتج والجميع قد جعلوا أهل راتج ولد زعورا بن جشم أخي عبد الأشهل بن جشم وإنما ابن إسحاق جعلهم في أول كلامه منهم وفي آخر كلامه من بني عبد الأشهل وهو جعل هذا زعورا بن جشم بن عبد الأشهل وزعورا بن عبد الأشهل هو ابنه لصلبه ليس بينهما جشم ولا غيره فلو كان بينهما أب آخر لقلنا إنهم اختلفوا فيه كغيره وإنما هو ابنه لصلبه وهذا تناقض ظاهر والصحيح أنه من زعورا ابن أخي عبد الأشهل وقال عروة وموسى بن عقبة إنه استشهد بأحد وقال ابن الكلبي قتل يوم الخندق والأول أصح أخرجه الثلاثة * عتيك بالتاء فوقها نقطتان والياء تحتها نقطتان وآخره كاف'
WHERE id = 243
  AND content_ar LIKE '(ب د ع) إياس بن أوس %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 243;

-- id=244  ثابت بن وقش
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 244;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع س',
    content_ar = 'ثابت بن وقش بن زعورا الأنصاري كذا نسبه ابن منده وأبو نعيم وقال أبو عمر ثابت بن وقش بن زغبة بن زعورا بن عبد الأشهل فزاد في النسب زغبة وهو الصحيح ومثله قال الكلبي استشهد بأحد جعله النبي صلى الله عليه وسلم في الآطام هو وحسيل بن جابر أبو حذيفة بن اليمان لما سار إلى أحد وهما شيخان كبيران فقال أحدهما لصاحبه ما ننتظر والله ما نحن إلا هامة اليوم أو غدا فلو خرجنا أفلا نأخذ أسيافنا ثم نلحق برسول الله صلى الله عليه وسلم لعل الله أن يرزقنا الشهادة فأخذا أسيافهما حتى دخلا في الناس ولم يعلم بهما فأما ثابت فقتله المشركون وأما حسيل فاختلف عليه أسياف المسلمين وهم لا يعرفونه فقتلوه قاله ابن منده وأبو نعيم وأما أبو موسى فإنه استدركه على ابن منده فقال ثابت ورفاعة ابنا وقش بن زغبة بن زعورا بن عبد الأشهل قتلا يوم أحد وقتل معهما سلمة وعمر وابنا ثابت قال أبو موسى فرق ابن شاهين بين ثابت بن وقش هذا وبين ثابت بن وقش بن زعورا أخرجه الثلاثة وأبو موسى
(قلت) أنا لا أشك أنهما واحد وهذا فرق بعيد جدا وإنما أسقط بعض الرواة زغبة من النسب فإنهم جرت عادتهم بمثله كثيرا فلو أراد هذا المفرق بينهما أن ينسبهما لم يجد لهما إلا نسبا واحدا إلى زعورا بن عبد الأشهل وأنهما قتلا يوم أحد وهذا جميعه يدل أنهما واحد وقد نسب ابن الكلبي سلمة بن ثابت وعمرو بن ثابت بن وقش بن زغبة بن زعورا بن عبد الأشهل وأنهما قتلا يوم أحد فكيف يكون الاتحاد إلا هكذا وقال أيضا إن عمرا هو أصيرم بني عبد الأشهل الذي دخل الجنة ولم يصل صلاة قط والله أعلم'
WHERE id = 244
  AND content_ar LIKE '(ب د ع س) ثابت بن وق%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 244;

-- id=245  عمارة بن زياد بن السكن
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 245;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عمارة بن زياد بن السكن بن رافع الأنصاري الأشهلي تقدم نسبه عند ذكر أبيه استشهد يوم أحد أنبأنا أبو جعفر بن السمين بإسناده عن يونس بن بكير عن ابن إسحاق قال فحدثني الحصين بن عبد الرحمن عن محمود بن عمرو بن يزيد بن السكن أن رسول الله صلى الله عليه وسلم قال يوم أحد حين غشيه القوم من رجل يشري لنا نفسه فقام زياد بن السكن في خمسة نفر من الأنصار وبعض الناس يقول إنما هو عمارة بن زياد بن السكن فقاتلوا دون رسول الله صلى الله عليه وسلم رجلا رجلا يقتلون دونه حتى كان آخرهم زياد أو عمارة بن زياد فقاتل حتى أثبتته الجراحة ثم فاءت فئة من المسلمين فأجهضوهم عنه فقال رسول الله صلى الله عليه وسلم ادنوه مني فأدنوه منه فوسده قدمه فمات وخده على قدم رسول الله صلى الله عليه وسلم ولم يذكروه فيمن شهد بدرا وقال هشام بن الكلبي إن عمارة بن زياد بن السكن قتل يوم بدر وإن أباه زياد بن السكن قتل يوم أحد والله أعلم

أخرجه الثلاثة'
WHERE id = 245
  AND content_ar LIKE '(ب د ع) عمارة بن زيا%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 245;

-- id=246  يزيد بن حاطب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 246;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب س',
    content_ar = 'يزيد بن حاطب بن عمرو بن أمية بن رافع الأنصاري الأشهلي وقيل إنه من بني ظفر ومن نسبه في بني ظفر يقول يزيد بن حاطب بن أمية بن رافع بن سويد ابن حرام بن الهيثم بن ظفر أخبرنا أبو جعفر بإسناده عن يونس عن ابن إسحاق في تسمية من قتل يوم أحد من بني ظفر يزيد بن حاطب بن أمية بن رافع قال ابن إسحاق حدثني عاصم بن عمر بن قتادة أن رجلا منهم يدعى حاطب بن أمية بن رافع كان له ابن يقال له يزيد بن حاطب أصابته جراحة يوم أحد فأتي به إلى دار قومه وهو بالموت فاجتمع إليه أهل الدار فجعل المسلمون من الرجال والنساء يقولون أبشر يا ابن حاطب بالجنة قال وكان حاطب شيخا قد عسا في الجاهلية فنجم يومئذ بفاقة فقال بأي شئ تبشرونه أبجنة من حرمل غررتم والله هذا الغلام عن نفسه أخرجه أبو عمر وأبو موسى إلا أن أبا موسى لم ينسبه إنما قال يزيد بن حاطب قتل يوم أحد شهيدا'
WHERE id = 246
  AND content_ar LIKE '(ب س) يزيد بن حاطب ب%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 246;

-- id=247  عبيد بن التيهان
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 247;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب س',
    content_ar = 'عبيد بن التيهان بن مالك أخو أبي الهيثم بن

التيهان تقدم نسبه ويرد نسبه في أبي الهيثم مالك بن التيهان إن شاء الله تعالى ونسبه أبو عمر ها هنا إلى الأوس من الأنصار وخالفه غيره فجعلوه من حلفاء بني عبد الأشهل وممن قال هذا ابن إسحاق والواقدي وموسى بن عقبة وأبو معشر وكان ابن إسحاق والواقدي يقولان هو عبيد وقال موسى بن عقبة وأبو معشر وعبد الله بن محمد بن عمارة هو عتيك بن التيهان ووافقهم ابن الكلبي وعبيد هذا هو أحد السبعين الذين بايعوا رسول الله صلى الله عليه وسلم ليلة العقبة شهد بدرا وقتل يوم أحد شهيدا قتله عكرمة بن أبي جهل وقيل بل قتل بصفين مع علي أخرجه أبو عمر وأبو موسى إلا أن أبا موسى قال هو حليف بلي وهذا لم يقله غيره إنما من العلماء من جعله من الأنصار من أنفسهم ومنهم من جعله من بلي بالنسب وحلفه في الأنصار وأما قول أبي موسى فغريب'
WHERE id = 247
  AND content_ar LIKE '(ب س) عبيد بن التيها%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 247;

-- id=248  سعيد بن سويد
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 248;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سعيد ابن سويد بن قيس بن عامر بن عباد وقيل عبيد وهو الصواب بن الأبجر وهو خدرة الأنصاري الخدري وهو أخو سمرة بن جندب لأمه روى عنه ابناه عقبة وعبد الملك قتل يوم أحد شهيدا روى الأوزاعي عن ناب بن عمير عن ربيعة بن أبي عبد الرحمن عن عبد الملك بن سعد بن سويد عن أبيه أن النبي صلى الله عليه وسلم سئل عن اللقطة فقال عرفها سنة ثم احفظ عفاصها ووكاءها ثم استنفع بها والصواب رواية ربيعة عن يزيد مولى المنبعث عن زيد بن خالد الجهني أخبرنا إسماعيل بن علي بن عبيد الله وغيره قالوا بإسنادهم عن أبي عيسى الترمذي أخبرنا قتيبة حدثنا إسماعيل بن جعفر عن ربيعة بن أبي عبد الرحمن عن يزيد مولى المنبعث عن زيد بن خالد أن رجلا سأل النبي صلى الله عليه وسلم عن اللقطة فقال عرفها سنة الحديث وقد روي من غير وجه عن يزيد مولى المنبعث أخرجه الثلاثة'
WHERE id = 248
  AND content_ar LIKE '(ب د ع) سعيد ابن سوي%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
