-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 31/31 (1 صفوف)

-- id=249  الحارث بن أنس بن رافع
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 249;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'الحارث بن أنس ابن رافع بن امرئ القيس بن زيد بن عبد الأشهل الأنصاري الأوسي ثم الأشهلي

قال أبو عمر وليس هو أبو الحيسر شهد بدرا وقتل يوم أحد شهيدا ووافقه ابن إسحاق والكلبي أخرجه الثلاثة إلا أن أبا نعيم جعل هذا الحارث مختلفا فيه فذكره ابن أنس وقال خالف ابن إسحاق أبو معشر فقال الحارث بن أوس وقال عروة الحارث ابن أشيم هذا كلام أبي نعيم فقد جعل الثلاثة واحدا وخالفه ابن منده فجعلهما اثنين أحدهما الحارث بن أنس وقيل ابن أوس بن رافع والثاني الحارث بن أشيم وجعل أبو عمر الحارث بن أوس غير الحارث بن أنس بن رافع إلا أنه قال في الحارث ابن أنس بن مالك أخاف أن يكون ابن رافع الأشهلي على ما ذكره آنفا وخالفه ابن منده في نسبه فقال الحارث بن أنس بن رافع بن أوس بن حارثة من بني عبد الأشهل وفيه نظر فإنه خالف الجميع ولا عقب له أخرجه الثلاثة'
WHERE id = 249
  AND content_ar LIKE '(ب د ع) الحارث بن أن%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 249;
